import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';
type SortOption = 'date' | 'subject' | 'grade';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);

  const [isEditingGeneratedPlan, setIsEditingGeneratedPlan] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP). 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba.

PAMOKOS EIGOS STRUKTŪRA:
Privalai užpildyti 'lessonStages' objektą:
- 'introduction': Įvadas, sudominimas, tikslų paskelbimas.
- 'theory': Naujos medžiagos aiškinimas, teorinė dalis.
- 'practice': Praktinis darbas, užduočių atlikimas.
- 'consolidation': Žinių įtvirtinimas, grįžtamasis ryšys.
- 'summary': Apibendrinimas, refleksija.

Struktūra turi būti tiksliai tokia:
{
  "generalNotes": "Bendros pastabos mokytojui",
  "lessonType": "Tipas",
  "bpConnections": "Sąsajos su BP",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonStages": { "introduction": "", "theory": "", "practice": "", "consolidation": "", "summary": "" },
  "differentiation": { "gifted": "", "general": "", "struggling": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Patarimai integracijai/išvykai",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė"
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);
    setIsEditingGeneratedPlan(false);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Tipas: ${lessonType}
      - Tikslas: ${goal}
      - Veiklos: ${activities}
      - Vertinimas: ${evaluationType}
      - Iššūkiai: ${consultationChallenges}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Išvyka: ${isOutsideInput ? locationDetails : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą formatą.");
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    let textToCopy = text;
    if (field === 'diary-topic') {
      textToCopy = textToCopy
        .replace(/^Temą:\s*/gm, '')
        .replace(/^Klasės darbą:\s*/gm, '')
        .replace(/^Numatomus pasiekimus:\s*/gm, '');
    }

    navigator.clipboard.writeText(textToCopy).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType,
      groundingUrls
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
    setIsEditingGeneratedPlan(false);
  };

  const handleUpdateGeneratedPlan = () => {
    if (!editedPlan) return;

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => {
        if (p.id === activePlanId) {
          return { 
            ...p, 
            plan: editedPlan,
            title: `${editedPlan.lessonOverview.topic || p.subject}` 
          };
        }
        return p;
      }));
    }

    setLessonPlan(editedPlan);
    setIsEditingGeneratedPlan(false);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return;
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
      setIsEditingGeneratedPlan(false);
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = { ...editedPlan };
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const currentPlan = isEditingGeneratedPlan ? editedPlan : lessonPlan;

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => {
      if (sortBy === 'date') return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
      if (sortBy === 'subject') return (a.subject || '').localeCompare(b.subject || '');
      if (sortBy === 'grade') return (a.grade || '').localeCompare(b.grade || '', undefined, { numeric: true });
      return 0;
    });

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Naujas planas</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba" required />
            </div>
            <div className="form-group">
              <label>Klasė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodis" required />
            </div>
            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Paieška..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !currentPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir paspauskite "Generuoti".</p>
            </div>
          )}

          {currentPlan && (
            <div className="lesson-plan-result">
              <div className="export-container" style={{display: 'flex', gap: '10px', marginBottom: '20px', position: 'sticky', top: 0, background: 'var(--surface-color)', padding: '10px 0', zIndex: 10}}>
                {!isEditingGeneratedPlan ? (
                  <>
                    <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti planą 💾</button>
                    <button onClick={() => setIsEditingGeneratedPlan(true)} className="external-link-button">Redaguoti turinį ✏️</button>
                  </>
                ) : (
                  <>
                    <button onClick={handleUpdateGeneratedPlan} className="save-button" style={{backgroundColor: 'var(--success-color)'}}>Baigti redagavimą ✅</button>
                    <button onClick={() => { setIsEditingGeneratedPlan(false); setEditedPlan(lessonPlan); }} className="cancel-edit-button">Atšaukti pakeitimus ❌</button>
                  </>
                )}
              </div>

              {/* General Notes */}
              <div className="card general-notes-card">
                <h3>📝 Pastabos mokytojui</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.generalNotes} onChange={e => updateEditedField('generalNotes', e.target.value)} style={{width: '100%', minHeight: '80px'}} />
                ) : (
                  <p>{currentPlan.generalNotes}</p>
                )}
              </div>

              {/* BP Connections */}
              <div className="card grounding-card" style={{borderLeftColor: 'var(--info-color)'}}>
                <h3>📚 BP sąsajos</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.bpConnections} onChange={e => updateEditedField('bpConnections', e.target.value)} style={{width: '100%', minHeight: '100px'}} />
                ) : (
                  <p style={{whiteSpace: 'pre-wrap'}}>{currentPlan.bpConnections}</p>
                )}
                {groundingUrls.length > 0 && !isEditingGeneratedPlan && (
                  <div className="sources-list" style={{marginTop: '10px'}}>
                    {groundingUrls.map((u, i) => <a key={i} href={u.uri} target="_blank" style={{display: 'block', fontSize: '0.8rem'}}>🔗 {u.title}</a>)}
                  </div>
                )}
              </div>

              {/* Overview */}
              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga</h3>
                <div style={{display: 'grid', gap: '10px'}}>
                  <div><strong>Tema:</strong> {isEditingGeneratedPlan ? <input className="edit-input" value={editedPlan?.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} style={{width: '100%'}} /> : currentPlan.lessonOverview.topic}</div>
                  <div><strong>Tikslas:</strong> {isEditingGeneratedPlan ? <textarea className="edit-textarea" value={editedPlan?.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} style={{width: '100%'}} /> : currentPlan.lessonOverview.goal}</div>
                  <div><strong>Gebėjimai:</strong> {isEditingGeneratedPlan ? <textarea className="edit-textarea" value={editedPlan?.lessonOverview.competencies} onChange={e => updateEditedField('lessonOverview.competencies', e.target.value)} style={{width: '100%'}} /> : currentPlan.lessonOverview.competencies}</div>
                  <div><strong>Vertinimas:</strong> {isEditingGeneratedPlan ? <textarea className="edit-textarea" value={editedPlan?.lessonOverview.evaluation} onChange={e => updateEditedField('lessonOverview.evaluation', e.target.value)} style={{width: '100%'}} /> : currentPlan.lessonOverview.evaluation}</div>
                </div>
              </div>

              {/* Stages */}
              <div className="card lesson-stages-card">
                <h3>🛤️ Pamokos eiga</h3>
                {Object.entries({
                  introduction: '🏁 Įvadas',
                  theory: '🎓 Teorija',
                  practice: '✍️ Praktika',
                  consolidation: '🧩 Įtvirtinimas',
                  summary: '🏁 Apibendrinimas'
                }).map(([id, label]) => (
                  <div key={id} className="stage-item">
                    <strong>{label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.lessonStages as any)?.[id]} onChange={e => updateEditedField(`lessonStages.${id}`, e.target.value)} style={{width: '100%', marginTop: '5px'}} />
                    ) : (
                      <p>{(currentPlan.lessonStages as any)?.[id]}</p>
                    )}
                  </div>
                ))}
              </div>

              {/* Differentiation */}
              <div className="card lesson-activities-card" style={{borderLeftColor: 'var(--warning-color)'}}>
                <h3>🎨 Diferencijavimas</h3>
                {Object.entries({
                  general: '🙂 Bendra',
                  gifted: '🚀 Gabesniems',
                  struggling: '🌱 Pagalba'
                }).map(([id, label]) => (
                  <div key={id} style={{marginBottom: '10px'}}>
                    <strong>{label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.differentiation as any)?.[id]} onChange={e => updateEditedField(`differentiation.${id}`, e.target.value)} style={{width: '100%', marginTop: '5px'}} />
                    ) : (
                      <p>{(currentPlan.differentiation as any)?.[id]}</p>
                    )}
                  </div>
                ))}
              </div>

              {/* Homework */}
              <div className="card homework-card" style={{borderLeftColor: 'var(--primary-color)'}}>
                <h3>🏠 Namų darbai (Išsamiai)</h3>
                <div><strong>Tikslas:</strong> {isEditingGeneratedPlan ? <textarea className="edit-textarea" value={editedPlan?.homework.purpose} onChange={e => updateEditedField('homework.purpose', e.target.value)} style={{width: '100%'}} /> : currentPlan.homework.purpose}</div>
                <div style={{marginTop: '10px'}}>
                   {Object.entries({ general: '🙂 Bendra', gifted: '🚀 Gabesniems', struggling: '🌱 Pagalba' }).map(([id, label]) => (
                    <div key={id} style={{marginTop: '5px'}}>
                      <strong>{label}:</strong>
                      {isEditingGeneratedPlan ? <textarea className="edit-textarea" value={(editedPlan?.homework as any)?.[id]} onChange={e => updateEditedField(`homework.${id}`, e.target.value)} style={{width: '100%'}} /> : <p>{(currentPlan.homework as any)?.[id]}</p>}
                    </div>
                  ))}
                </div>
              </div>

              {/* E-Diary */}
              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                {Object.entries({
                  'topicClassworkExpectations': 'Tema, darbas, pasiekimai',
                  'homework': 'Namų darbai (trumpai)',
                  'individualHomework': 'Individualūs namų darbai',
                  'notes': 'Pastabos'
                }).map(([key, label]) => (
                  <div key={key} style={{marginBottom: '10px'}}>
                    <label style={{fontSize: '0.8rem', fontWeight: 'bold'}}>{label}:</label>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.eDiaryEntry as any)?.[key]} onChange={e => updateEditedField(`eDiaryEntry.${key}`, e.target.value)} style={{width: '100%', background: '#0f172a'}} />
                    ) : (
                      <div className="diary-field">
                        <span style={{whiteSpace: 'pre-wrap'}}>{(currentPlan.eDiaryEntry as any)?.[key] || '---'}</span>
                        <button onClick={() => handleCopy((currentPlan.eDiaryEntry as any)?.[key], key)} className="copy-button">Kopijuoti</button>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              {/* Consultation & Motivation */}
              <div className="card consultation-card">
                <h3>🆘 Konsultacinė pagalba</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.consultationAdvice} onChange={e => updateEditedField('consultationAdvice', e.target.value)} style={{width: '100%'}} />
                ) : (
                  <p>{currentPlan.consultationAdvice}</p>
                )}
              </div>

              <div className="card motivation-card">
                <h3>💖 Motyvacija</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.motivation} onChange={e => updateEditedField('motivation', e.target.value)} style={{width: '100%', background: 'transparent'}} />
                ) : (
                  <p>{currentPlan.motivation}</p>
                )}
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Modals */}
      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Kaip naudotis?</h2>
            <p>1. Užpildykite formą.<br/>2. Sugeneruokite planą.<br/>3. Redaguokite bet kurią dalį.<br/>4. Išsaugokite!</p>
            <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
          </div>
        </div>
      )}

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Išsaugoti?</h2>
            <button onClick={executeSavePlan} className="save-button">Taip, išsaugoti</button>
            <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button">Ne</button>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Ištrinti?</h2>
            <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); }} className="save-button" style={{backgroundColor: 'var(--error-color)'}}>Trinti</button>
            <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Atšaukti</button>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';
type SortOption = 'date' | 'subject' | 'grade';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);

  const [isEditingGeneratedPlan, setIsEditingGeneratedPlan] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP). 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba.

PAMOKOS EIGOS STRUKTŪRA:
Privalai užpildyti 'lessonStages' objektą:
- 'introduction': Įvadas, sudominimas, tikslų paskelbimas.
- 'theory': Naujos medžiagos aiškinimas, teorinė dalis.
- 'practice': Praktinis darbas, užduočių atlikimas.
- 'consolidation': Žinių įtvirtinimas, grįžtamasis ryšys.
- 'summary': Apibendrinimas, refleksija.

Struktūra turi būti tiksliai tokia:
{
  "generalNotes": "Bendros pastabos mokytojui",
  "lessonType": "Tipas",
  "bpConnections": "Sąsajos su BP",
  "lessonOverview": { "topic": "", "goal": "", "competencies": "", "evaluation": "" },
  "lessonStages": { "introduction": "", "theory": "", "practice": "", "consolidation": "", "summary": "" },
  "differentiation": { "gifted": "", "general": "", "struggling": "" },
  "homework": { "purpose": "", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Temą: ...\\nKlasės darbą: ...\\nNumatomus pasiekimus: ...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Patarimai integracijai/išvykai",
  "consultationAdvice": "Patarimai dėl iššūkių",
  "motivation": "Padėkos žinutė"
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);
    setIsEditingGeneratedPlan(false);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Tipas: ${lessonType}
      - Tikslas: ${goal}
      - Veiklos: ${activities}
      - Vertinimas: ${evaluationType}
      - Iššūkiai: ${consultationChallenges}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Išvyka: ${isOutsideInput ? locationDetails : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą formatą.");
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    let textToCopy = text;
    if (field === 'diary-topic') {
      textToCopy = textToCopy
        .replace(/^Temą:\s*/gm, '')
        .replace(/^Klasės darbą:\s*/gm, '')
        .replace(/^Numatomus pasiekimus:\s*/gm, '');
    }

    navigator.clipboard.writeText(textToCopy).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType,
      groundingUrls
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
    setIsEditingGeneratedPlan(false);
  };

  const handleUpdateGeneratedPlan = () => {
    if (!editedPlan) return;

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => {
        if (p.id === activePlanId) {
          return { 
            ...p, 
            plan: editedPlan,
            title: `${editedPlan.lessonOverview.topic || p.subject}` 
          };
        }
        return p;
      }));
    }

    setLessonPlan(editedPlan);
    setIsEditingGeneratedPlan(false);
  };

  const handleLoadPlan = (id: string) => {
    if (editingPlanId) return;
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setGrade(p.grade || '');
      setSubject(p.subject || '');
      setIsEditingGeneratedPlan(false);
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = { ...editedPlan };
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const currentPlan = isEditingGeneratedPlan ? editedPlan : lessonPlan;

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => {
      if (sortBy === 'date') return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
      if (sortBy === 'subject') return (a.subject || '').localeCompare(b.subject || '');
      if (sortBy === 'grade') return (a.grade || '').localeCompare(b.grade || '', undefined, { numeric: true });
      return 0;
    });

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Jūsų pagalbininkas kūrybiškoms ir efektyvioms pamokoms</p>
        <div className="header-buttons">
          <button onClick={() => setShowOnboarding(true)} className="external-link-button">Kaip naudotis?</button>
          <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="external-link-button">BP nuoroda</a>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Naujas planas</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba" required />
            </div>
            <div className="form-group">
              <label>Klasė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodis" required />
            </div>
            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Paieška..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && <div className="loading-overlay"><div className="spinner-large"></div><p>Ruošiamas planas...</p></div>}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !currentPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje ir paspauskite "Generuoti".</p>
            </div>
          )}

          {currentPlan && (
            <div className="lesson-plan-result">
              <div className="export-container" style={{display: 'flex', gap: '10px', marginBottom: '20px', position: 'sticky', top: 0, background: 'var(--surface-color)', padding: '10px 0', zIndex: 10}}>
                {!isEditingGeneratedPlan ? (
                  <>
                    <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti planą 💾</button>
                    <button onClick={() => setIsEditingGeneratedPlan(true)} className="external-link-button">Redaguoti turinį ✏️</button>
                  </>
                ) : (
                  <>
                    <button onClick={handleUpdateGeneratedPlan} className="save-button" style={{backgroundColor: 'var(--success-color)'}}>Baigti redagavimą ✅</button>
                    <button onClick={() => { setIsEditingGeneratedPlan(false); setEditedPlan(lessonPlan); }} className="cancel-edit-button">Atšaukti pakeitimus ❌</button>
                  </>
                )}
              </div>

              {/* General Notes */}
              <div className="card general-notes-card">
                <h3>📝 Pastabos mokytojui</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.generalNotes} onChange={e => updateEditedField('generalNotes', e.target.value)} style={{width: '100%', minHeight: '80px'}} />
                ) : (
                  <p>{currentPlan.generalNotes}</p>
                )}
              </div>

              {/* BP Connections */}
              <div className="card grounding-card" style={{borderLeftColor: 'var(--info-color)'}}>
                <h3>📚 BP sąsajos</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.bpConnections} onChange={e => updateEditedField('bpConnections', e.target.value)} style={{width: '100%', minHeight: '100px'}} />
                ) : (
                  <p style={{whiteSpace: 'pre-wrap'}}>{currentPlan.bpConnections}</p>
                )}
                {groundingUrls.length > 0 && !isEditingGeneratedPlan && (
                  <div className="sources-list" style={{marginTop: '10px'}}>
                    {groundingUrls.map((u, i) => <a key={i} href={u.uri} target="_blank" style={{display: 'block', fontSize: '0.8rem'}}>🔗 {u.title}</a>)}
                  </div>
                )}
              </div>

              {/* Overview */}
              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga</h3>
                <div style={{display: 'grid', gap: '15px'}}>
                  <div>
                    <strong>Tema:</strong>
                    {isEditingGeneratedPlan ? (
                      <input 
                        type="text"
                        className="edit-input" 
                        value={editedPlan?.lessonOverview.topic} 
                        onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} 
                        style={{width: '100%', marginTop: '5px'}} 
                      />
                    ) : (
                      <span style={{marginLeft: '10px'}}>{currentPlan.lessonOverview.topic}</span>
                    )}
                  </div>
                  <div>
                    <strong>Tikslas:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea 
                        className="edit-textarea" 
                        value={editedPlan?.lessonOverview.goal} 
                        onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} 
                        style={{width: '100%', minHeight: '100px', marginTop: '5px'}} 
                      />
                    ) : (
                      <p style={{marginTop: '5px'}}>{currentPlan.lessonOverview.goal}</p>
                    )}
                  </div>
                  <div>
                    <strong>Gebėjimai:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={editedPlan?.lessonOverview.competencies} onChange={e => updateEditedField('lessonOverview.competencies', e.target.value)} style={{width: '100%', marginTop: '5px'}} />
                    ) : (
                      <p style={{marginTop: '5px'}}>{currentPlan.lessonOverview.competencies}</p>
                    )}
                  </div>
                  <div>
                    <strong>Vertinimas:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={editedPlan?.lessonOverview.evaluation} onChange={e => updateEditedField('lessonOverview.evaluation', e.target.value)} style={{width: '100%', marginTop: '5px'}} />
                    ) : (
                      <p style={{marginTop: '5px'}}>{currentPlan.lessonOverview.evaluation}</p>
                    )}
                  </div>
                </div>
              </div>

              {/* Stages */}
              <div className="card lesson-stages-card">
                <h3>🛤️ Pamokos eiga</h3>
                {Object.entries({
                  introduction: '🏁 Įvadas',
                  theory: '🎓 Teorija',
                  practice: '✍️ Praktika',
                  consolidation: '🧩 Įtvirtinimas',
                  summary: '🏁 Apibendrinimas'
                }).map(([id, label]) => (
                  <div key={id} className="stage-item">
                    <strong>{label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.lessonStages as any)?.[id]} onChange={e => updateEditedField(`lessonStages.${id}`, e.target.value)} style={{width: '100%', marginTop: '5px'}} />
                    ) : (
                      <p>{(currentPlan.lessonStages as any)?.[id]}</p>
                    )}
                  </div>
                ))}
              </div>

              {/* Differentiation */}
              <div className="card lesson-activities-card" style={{borderLeftColor: 'var(--warning-color)'}}>
                <h3>🎨 Diferencijavimas</h3>
                {Object.entries({
                  general: '🙂 Bendra',
                  gifted: '🚀 Gabesniems',
                  struggling: '🌱 Pagalba'
                }).map(([id, label]) => (
                  <div key={id} style={{marginBottom: '10px'}}>
                    <strong>{label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.differentiation as any)?.[id]} onChange={e => updateEditedField(`differentiation.${id}`, e.target.value)} style={{width: '100%', marginTop: '5px'}} />
                    ) : (
                      <p>{(currentPlan.differentiation as any)?.[id]}</p>
                    )}
                  </div>
                ))}
              </div>

              {/* Homework */}
              <div className="card homework-card" style={{borderLeftColor: 'var(--primary-color)'}}>
                <h3>🏠 Namų darbai (Išsamiai)</h3>
                <div><strong>Tikslas:</strong> {isEditingGeneratedPlan ? <textarea className="edit-textarea" value={editedPlan?.homework.purpose} onChange={e => updateEditedField('homework.purpose', e.target.value)} style={{width: '100%'}} /> : currentPlan.homework.purpose}</div>
                <div style={{marginTop: '10px'}}>
                   {Object.entries({ general: '🙂 Bendra', gifted: '🚀 Gabesniems', struggling: '🌱 Pagalba' }).map(([id, label]) => (
                    <div key={id} style={{marginTop: '5px'}}>
                      <strong>{label}:</strong>
                      {isEditingGeneratedPlan ? <textarea className="edit-textarea" value={(editedPlan?.homework as any)?.[id]} onChange={e => updateEditedField(`homework.${id}`, e.target.value)} style={{width: '100%'}} /> : <p>{(currentPlan.homework as any)?.[id]}</p>}
                    </div>
                  ))}
                </div>
              </div>

              {/* E-Diary */}
              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                {Object.entries({
                  'topicClassworkExpectations': 'Tema, darbas, pasiekimai',
                  'homework': 'Namų darbai (trumpai)',
                  'individualHomework': 'Individualūs namų darbai',
                  'notes': 'Pastabos'
                }).map(([key, label]) => (
                  <div key={key} style={{marginBottom: '10px'}}>
                    <label style={{fontSize: '0.8rem', fontWeight: 'bold'}}>{label}:</label>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.eDiaryEntry as any)?.[key]} onChange={e => updateEditedField(`eDiaryEntry.${key}`, e.target.value)} style={{width: '100%', background: '#0f172a'}} />
                    ) : (
                      <div className="diary-field">
                        <span style={{whiteSpace: 'pre-wrap'}}>{(currentPlan.eDiaryEntry as any)?.[key] || '---'}</span>
                        <button onClick={() => handleCopy((currentPlan.eDiaryEntry as any)?.[key], key)} className="copy-button">Kopijuoti</button>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              {/* Consultation & Motivation */}
              <div className="card consultation-card">
                <h3>🆘 Konsultacinė pagalba</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.consultationAdvice} onChange={e => updateEditedField('consultationAdvice', e.target.value)} style={{width: '100%'}} />
                ) : (
                  <p>{currentPlan.consultationAdvice}</p>
                )}
              </div>

              <div className="card motivation-card">
                <h3>💖 Motyvacija</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.motivation} onChange={e => updateEditedField('motivation', e.target.value)} style={{width: '100%', background: 'transparent'}} />
                ) : (
                  <p>{currentPlan.motivation}</p>
                )}
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Modals */}
      {showOnboarding && (
        <div className="modal-overlay" onClick={() => setShowOnboarding(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Kaip naudotis?</h2>
            <p>1. Užpildykite formą.<br/>2. Sugeneruokite planą.<br/>3. Redaguokite bet kurią dalį.<br/>4. Išsaugokite!</p>
            <button onClick={() => setShowOnboarding(false)} className="button-primary">Supratau</button>
          </div>
        </div>
      )}

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Išsaugoti?</h2>
            <button onClick={executeSavePlan} className="save-button">Taip, išsaugoti</button>
            <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button">Ne</button>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Ištrinti?</h2>
            <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); }} className="save-button" style={{backgroundColor: 'var(--error-color)'}}>Trinti</button>
            <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Atšaukti</button>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

