  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP) ir kompetencijas. 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba, griežtai vadovaujantis šiais šaltiniais:
1. BP (Bendrosios programos): https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos
2. Skaitmeninės priemonės: https://emokykla.lt/skaitmenines-mokymo-priemones/priemones
3. Kompetencijų aprašas: https://emokykla.lt/bendrosios-programos/kompetencijos

Privalai įtraukti specifines kompetencijas (pažinimo, skaitmeninę, kūrybiškumo, komunikavimo, kultūrinę, pilietiškumo, socialinę, emocinę ir sveikos gyvensenos).
Rengdamas eigą, naudokis ilgalaikių planų pavyzdžiais iš emokykla.lt.

Struktūra turi būti tiksliai tokia:
{
  "generalNotes": "Bendros pastabos mokytojui, remiantis BP rekomendacijomis",
  "lessonType": "Tipas",
  "bpConnections": "Išsamios sąsajos su BP pasiekimų sritimis ir mokymo turiniu",
  "lessonOverview": { 
    "topic": "Tikslus temos pavadinimas", 
    "goal": "Pamokos uždavinys suformuluotas pagal SMART kriterijus", 
    "competencies": "Konkrečios ugdomos kompetencijos iš LT programos", 
    "evaluation": "Formuojamojo/apibendrinamojo vertinimo strategija" 
  },
  "lessonStages": { 
    "introduction": "Sužadinimas, tikslų kėlimas", 
    "theory": "Mokymosi medžiaga, AI/Skaitmeninių įrankių (pvz. Miro, Canva) naudojimas", 
    "practice": "Aktyvaus mokymosi veiklos", 
    "consolidation": "Žinių pasitikrinimas", 
    "summary": "Refleksija ir grįžtamasis ryšys" 
  },
  "differentiation": { "gifted": "Užduotys aukštesniam lygiui", "general": "Pagrindinis lygis", "struggling": "Sustiprinta pagalba/pastoliavimas" },
  "homework": { "purpose": "Tikslas", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Tema: ...\\nKlasės darbas: ...\\nLaukiami rezultatai: ...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Integracija arba skaitmeninių priemonių panaudojimas (pvz. Classroom, Miro)",
  "consultationAdvice": "Sunkumų numatymas ir pagalba",
  "motivation": "Mokytojo palaikymo žinutė"
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);
    setIsEditingGeneratedPlan(false);

    const prompt = `
      Sukurk pamokos planą vadovaujantis LT BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Tipas: ${lessonType}
      - Tikslas: ${goal}
      - Papildomos veiklos: ${activities}
      - Vertinimas: ${evaluationType}
      - Naudoti įrankiai: Miro, Canva, Google Classroom (jei tinkama temai)
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("AI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType,
      groundingUrls
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
    setIsEditingGeneratedPlan(false);
  };

  const handleUpdateGeneratedPlan = () => {
    if (!editedPlan) return;
    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? { ...p, plan: editedPlan, title: editedPlan.lessonOverview.topic } : p));
    }
    setLessonPlan(editedPlan);
    setIsEditingGeneratedPlan(false);
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setIsEditingGeneratedPlan(false);
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = { ...editedPlan };
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const currentPlan = isEditingGeneratedPlan ? editedPlan : lessonPlan;

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Griežtai vadovaujantis Lietuvos Bendrosiomis programomis ir kompetencijomis</p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai:</h3>
              <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones/priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Skaitmeninės priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai:</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Naujas planas</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Biologija" required />
            </div>
            <div className="form-group">
              <label>Klasė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7 kl." required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Ląstelės sandara" required />
            </div>
            <div className="form-group">
              <label>Tikslas (nebūtina)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="Jei turite konkretų uždavinį..." />
            </div>
            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>Generuojama pagal emokykla.lt standartus...</p>
              <p style={{fontSize: '0.8rem', marginTop: '10px'}}>Tai gali užtrukti iki 30 sekundžių</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !currentPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Įveskite pamokos duomenis kairėje. AI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {currentPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                {!isEditingGeneratedPlan ? (
                  <>
                    <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                    <button onClick={() => setIsEditingGeneratedPlan(true)} className="external-link-button">Redaguoti ✏️</button>
                  </>
                ) : (
                  <>
                    <button onClick={handleUpdateGeneratedPlan} className="save-button" style={{backgroundColor: 'var(--success-color)'}}>Baigti ✅</button>
                    <button onClick={() => { setIsEditingGeneratedPlan(false); setEditedPlan(lessonPlan); }} className="cancel-edit-button">Atšaukti ❌</button>
                  </>
                )}
              </div>

              <div className="card grounding-card">
                <h3>📚 Sąsajos su BP ir Kompetencijomis</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.bpConnections} onChange={e => updateEditedField('bpConnections', e.target.value)} style={{minHeight: '120px'}} />
                ) : (
                  <p style={{whiteSpace: 'pre-wrap'}}>{currentPlan.bpConnections}</p>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga</h3>
                <div className="overview-grid">
                  <div><strong>Tema:</strong> {isEditingGeneratedPlan ? <input className="edit-input" value={editedPlan?.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} /> : currentPlan.lessonOverview.topic}</div>
                  <div><strong>Tikslas:</strong> {isEditingGeneratedPlan ? <textarea className="edit-textarea" value={editedPlan?.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} /> : currentPlan.lessonOverview.goal}</div>
                  <div><strong>Kompetencijos:</strong> {isEditingGeneratedPlan ? <textarea className="edit-textarea" value={editedPlan?.lessonOverview.competencies} onChange={e => updateEditedField('lessonOverview.competencies', e.target.value)} /> : currentPlan.lessonOverview.competencies}</div>
                </div>
              </div>

              <div className="card lesson-stages-card">
                <h3>🛤️ Pamokos eiga</h3>
                {Object.entries({
                  introduction: '🏁 Įvadas',
                  theory: '🎓 Teorija',
                  practice: '✍️ Praktika',
                  consolidation: '🧩 Įtvirtinimas',
                  summary: '🏁 Apibendrinimas'
                }).map(([id, label]) => (
                  <div key={id} className="stage-item">
                    <strong>{label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.lessonStages as any)?.[id]} onChange={e => updateEditedField(`lessonStages.${id}`, e.target.value)} />
                    ) : (
                      <p>{(currentPlan.lessonStages as any)?.[id]}</p>
                    )}
                  </div>
                ))}
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'individualHomework'].map(key => (
                  <div key={key} style={{marginBottom: '10px'}}>
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'N.D.' : 'Indiv. N.D.'}</label>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.eDiaryEntry as any)?.[key]} onChange={e => updateEditedField(`eDiaryEntry.${key}`, e.target.value)} />
                    ) : (
                      <div className="diary-field">
                        <span>{(currentPlan.eDiaryEntry as any)?.[key] || '---'}</span>
                        <button onClick={() => handleCopy((currentPlan.eDiaryEntry as any)?.[key], key)} className="copy-button">Kopijuoti</button>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p>{currentPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Išsaugoti planą?</h2>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="save-button">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Tikrai trinti?</h2>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); }} className="save-button" style={{backgroundColor: 'var(--error-color)'}}>Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Ne</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  /* Dark Theme Colors */
  --primary-color: #3b82f6;
  --primary-color-dark: #2563eb;
  --primary-color-light: #1e293b;
  --primary-color-focus: rgba(59, 130, 246, 0.3);
  --secondary-color: #10b981;
  --secondary-color-dark: #059669;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --shadow-color: rgba(0, 0, 0, 0.4);
  --error-color: #ef4444;
  --success-color: #10b981;
  --warning-color: #f59e0b;
  --info-color: #8b5cf6;
  --white: #ffffff;

  /* Typography */
  --font-family: 'Inter', sans-serif;
  --spacing-lg: 1rem;
  --spacing-xl: 1.5rem;
  --border-radius-md: 8px;
  --border-radius-lg: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font-family);
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--spacing-lg);
}

.header {
  text-align: center;
  margin-bottom: 2rem;
  padding: var(--spacing-xl);
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.header h1 { color: var(--heading-color); margin-bottom: 0.5rem; }

.header-sections {
  display: flex;
  justify-content: space-around;
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  flex-wrap: wrap;
  gap: 20px;
}

.resource-links, .tool-links {
  display: flex;
  align-items: center;
  gap: 12px;
}

.resource-links h3, .tool-links h3 {
  font-size: 0.9rem;
  color: var(--text-color-light);
  margin-right: 5px;
}

.mini-link {
  color: var(--primary-color);
  text-decoration: none;
  font-size: 0.85rem;
  padding: 4px 8px;
  border-radius: 4px;
  background-color: rgba(59, 130, 246, 0.1);
  transition: background 0.2s;
}

.mini-link:hover { background-color: rgba(59, 130, 246, 0.2); }

.tool-button {
  padding: 6px 14px;
  border-radius: 6px;
  color: white;
  text-decoration: none;
  font-size: 0.85rem;
  font-weight: 600;
  transition: opacity 0.2s;
}

.tool-button.classroom { background-color: #1e8e3e; }
.tool-button.miro { background-color: #ffcc00; color: #000; }
.tool-button.canva { background-color: #00c4cc; }
.tool-button:hover { opacity: 0.8; }

.main-content {
  display: grid;
  grid-template-columns: 350px 1fr;
  gap: 2rem;
}

.form-container {
  background-color: var(--surface-color);
  padding: 1.5rem;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
  height: fit-content;
}

.form-group { margin-bottom: 1rem; }
.form-group label { display: block; color: var(--heading-color); margin-bottom: 4px; font-weight: 500; }
.form-group input, .form-group textarea {
  width: 100%;
  padding: 8px;
  border-radius: 6px;
  border: 1px solid var(--border-color);
  background: #0f172a;
  color: white;
}

.generate-button {
  width: 100%;
  padding: 10px;
  background: var(--primary-color);
  color: white;
  border: none;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
}

.results-container {
  background-color: var(--surface-color);
  padding: 2rem;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
  min-height: 600px;
}

.card {
  background: #1e293b;
  border-left: 4px solid var(--primary-color);
  padding: 1.25rem;
  margin-bottom: 1.25rem;
  border-radius: 0 8px 8px 0;
}

.card h3 { margin-bottom: 0.75rem; color: var(--heading-color); }

.diary-field {
  display: flex;
  justify-content: space-between;
  background: #0f172a;
  padding: 10px;
  border-radius: 6px;
  margin-top: 5px;
}

.copy-button {
  background: var(--primary-color);
  color: white;
  border: none;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 0.75rem;
  cursor: pointer;
}

.edit-input, .edit-textarea {
  width: 100%;
  padding: 8px;
  background: #0f172a;
  color: white;
  border: 1px solid var(--primary-color);
  border-radius: 4px;
}

.export-container {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}

.save-button { background: var(--success-color); color: white; border: none; padding: 8px 16px; border-radius: 6px; cursor: pointer; }

.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.8);
  display: flex; justify-content: center; align-items: center;
  z-index: 1000;
}

.modal-content {
  background: var(--surface-color);
  padding: 2rem;
  border-radius: 12px;
  text-align: center;
}

.modal-actions { display: flex; gap: 10px; margin-top: 20px; justify-content: center; }

@media (max-width: 900px) {
  .main-content { grid-template-columns: 1fr; }
}

.spinner {
  width: 20px; height: 20px;
  border: 2px solid rgba(255,255,255,0.3);
  border-top-color: white;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';
type SortOption = 'date' | 'subject' | 'grade';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);

  const [isEditingGeneratedPlan, setIsEditingGeneratedPlan] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP) ir kompetencijas. 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba, griežtai vadovaujantis šiais šaltiniais:
1. BP (Bendrosios programos): https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos
2. Skaitmeninės priemonės: https://emokykla.lt/skaitmenines-mokymo-priemones/priemones
3. Kompetencijų aprašas: https://emokykla.lt/bendrosios-programos/kompetencijos

Privalai įtraukti specifines kompetencijas (pažinimo, skaitmeninę, kūrybiškumo, komunikavimo, kultūrinę, pilietiškumo, socialinę, emocinę ir sveikos gyvensenos).
Rengdamas eigą, naudokis ilgalaikių planų pavyzdžiais iš emokykla.lt.

Struktūra turi būti tiksliai tokia:
{
  "generalNotes": "Bendros pastabos mokytojui, remiantis BP rekomendacijomis",
  "lessonType": "Tipas",
  "bpConnections": "Išsamios sąsajos su BP pasiekimų sritimis ir mokymo turiniu",
  "lessonOverview": { 
    "topic": "Tikslus temos pavadinimas", 
    "goal": "Pamokos uždavinys suformuluotas pagal SMART kriterijus", 
    "competencies": "Konkrečios ugdomos kompetencijos iš LT programos", 
    "evaluation": "Formuojamojo/apibendrinamojo vertinimo strategija" 
  },
  "lessonStages": { 
    "introduction": "Sužadinimas, tikslų kėlimas", 
    "theory": "Mokymosi medžiaga, DI/Skaitmeninių įrankių (pvz. Miro, Canva) naudojimas", 
    "practice": "Aktyvaus mokymosi veiklos", 
    "consolidation": "Žinių pasitikrinimas", 
    "summary": "Refleksija ir grįžtamasis ryšys" 
  },
  "differentiation": { "gifted": "Užduotys aukštesniam lygiui", "general": "Pagrindinis lygis", "struggling": "Sustiprinta pagalba/pastoliavimas" },
  "homework": { "purpose": "Tikslas", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Tema: ...\\nKlasės darbas: ...\\nLaukiami rezultatai: ...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Integracija arba skaitmeninių priemonių panaudojimas (pvz. Classroom, Miro)",
  "consultationAdvice": "Sunkumų numatymas ir pagalba",
  "motivation": "Mokytojo palaikymo žinutė"
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);
    setIsEditingGeneratedPlan(false);

    const prompt = `
      Sukurk pamokos planą vadovaujantis LT BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Tipas: ${lessonType}
      - Tikslas: ${goal}
      - Papildomos veiklos: ${activities}
      - Vertinimas: ${evaluationType}
      - Naudoti įrankiai: Miro, Canva, Google Classroom (jei tinkama temai)
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("DI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType,
      groundingUrls
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
    setIsEditingGeneratedPlan(false);
  };

  const handleUpdateGeneratedPlan = () => {
    if (!editedPlan) return;
    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? { ...p, plan: editedPlan, title: editedPlan.lessonOverview.topic } : p));
    }
    setLessonPlan(editedPlan);
    setIsEditingGeneratedPlan(false);
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setIsEditingGeneratedPlan(false);
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = { ...editedPlan };
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const currentPlan = isEditingGeneratedPlan ? editedPlan : lessonPlan;

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>Griežtai vadovaujantis Lietuvos Bendrosiomis programomis ir kompetencijomis</p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai:</h3>
              <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones/priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Skaitmeninės priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai:</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Naujas planas</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Biologija" required />
            </div>
            <div className="form-group">
              <label>Klasė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7 kl." required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Ląstelės sandara" required />
            </div>
            <div className="form-group">
              <label>Tikslas (nebūtina)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="Jei turite konkretų uždavinį..." />
            </div>
            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>Generuojama pagal emokykla.lt standartus...</p>
              <p style={{fontSize: '0.8rem', marginTop: '10px'}}>Tai gali užtrukti iki 30 sekundžių</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !currentPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Įveskite pamokos duomenis kairėje. DI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {currentPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                {!isEditingGeneratedPlan ? (
                  <>
                    <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                    <button onClick={() => setIsEditingGeneratedPlan(true)} className="external-link-button">Redaguoti ✏️</button>
                  </>
                ) : (
                  <>
                    <button onClick={handleUpdateGeneratedPlan} className="save-button" style={{backgroundColor: 'var(--success-color)'}}>Baigti ✅</button>
                    <button onClick={() => { setIsEditingGeneratedPlan(false); setEditedPlan(lessonPlan); }} className="cancel-edit-button">Atšaukti ❌</button>
                  </>
                )}
              </div>

              <div className="card grounding-card">
                <h3>📚 Sąsajos su BP ir Kompetencijomis</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.bpConnections} onChange={e => updateEditedField('bpConnections', e.target.value)} style={{minHeight: '120px'}} />
                ) : (
                  <p style={{whiteSpace: 'pre-wrap'}}>{currentPlan.bpConnections}</p>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga</h3>
                <div className="overview-grid">
                  <div className="overview-field">
                    <strong>Tema:</strong> 
                    {isEditingGeneratedPlan ? (
                      <input 
                        type="text" 
                        className="edit-input" 
                        value={editedPlan?.lessonOverview.topic} 
                        onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} 
                        style={{marginTop: '5px', width: '100%'}}
                      />
                    ) : (
                      <span> {currentPlan.lessonOverview.topic}</span>
                    )}
                  </div>
                  <div className="overview-field" style={{marginTop: '15px'}}>
                    <strong>Tikslas:</strong> 
                    {isEditingGeneratedPlan ? (
                      <textarea 
                        className="edit-textarea" 
                        value={editedPlan?.lessonOverview.goal} 
                        onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} 
                        style={{marginTop: '5px', width: '100%', minHeight: '80px'}}
                      />
                    ) : (
                      <p style={{marginTop: '5px'}}>{currentPlan.lessonOverview.goal}</p>
                    )}
                  </div>
                  <div className="overview-field" style={{marginTop: '15px'}}>
                    <strong>Kompetencijos:</strong> 
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={editedPlan?.lessonOverview.competencies} onChange={e => updateEditedField('lessonOverview.competencies', e.target.value)} style={{marginTop: '5px', width: '100%'}} />
                    ) : (
                      <p style={{marginTop: '5px'}}>{currentPlan.lessonOverview.competencies}</p>
                    )}
                  </div>
                </div>
              </div>

              <div className="card lesson-stages-card">
                <h3>🛤️ Pamokos eiga</h3>
                {Object.entries({
                  introduction: '🏁 Įvadas',
                  theory: '🎓 Teorija',
                  practice: '✍️ Praktika',
                  consolidation: '🧩 Įtvirtinimas',
                  summary: '🏁 Apibendrinimas'
                }).map(([id, label]) => (
                  <div key={id} className="stage-item">
                    <strong>{label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.lessonStages as any)?.[id]} onChange={e => updateEditedField(`lessonStages.${id}`, e.target.value)} />
                    ) : (
                      <p>{(currentPlan.lessonStages as any)?.[id]}</p>
                    )}
                  </div>
                ))}
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'individualHomework'].map(key => (
                  <div key={key} style={{marginBottom: '10px'}}>
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'N.D.' : 'Indiv. N.D.'}</label>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.eDiaryEntry as any)?.[key]} onChange={e => updateEditedField(`eDiaryEntry.${key}`, e.target.value)} />
                    ) : (
                      <div className="diary-field">
                        <span style={{whiteSpace: 'pre-wrap'}}>{(currentPlan.eDiaryEntry as any)?.[key] || '---'}</span>
                        <button onClick={() => handleCopy((currentPlan.eDiaryEntry as any)?.[key], key)} className="copy-button">Kopijuoti</button>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p>{currentPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Išsaugoti planą?</h2>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="save-button">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Tikrai trinti?</h2>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); }} className="save-button" style={{backgroundColor: 'var(--error-color)'}}>Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Ne</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';
type SortOption = 'date' | 'subject' | 'grade';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);

  const [isEditingGeneratedPlan, setIsEditingGeneratedPlan] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP) ir kompetencijas. 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba, griežtai vadovaujantis šiais šaltiniais:
1. BP (Bendrosios programos): https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos
2. Skaitmeninės priemonės: https://emokykla.lt/skaitmenines-mokymo-priemones/priemones
3. Kompetencijų aprašas: https://emokykla.lt/bendrosios-programos/kompetencijos

Privalai įtraukti specifines kompetencijas (pažinimo, skaitmeninę, kūrybiškumo, komunikavimo, kultūrinę, pilietiškumo, socialinę, emocinę ir sveikos gyvensenos).
Rengdamas eigą, naudokis ilgalaikių planų pavyzdžiais iš emokykla.lt.

Struktūra turi būti tiksliai tokia:
{
  "generalNotes": "Bendros pastabos mokytojui, remiantis BP rekomendacijomis",
  "lessonType": "Tipas",
  "bpConnections": "Išsamios sąsajos su BP pasiekimų sritimis ir mokymo turiniu",
  "lessonOverview": { 
    "topic": "Tikslus temos pavadinimas", 
    "goal": "Pamokos uždavinys suformuluotas pagal SMART kriterijus", 
    "competencies": "Konkrečios ugdomos kompetencijos iš LT programos", 
    "evaluation": "Formuojamojo/apibendrinamojo vertinimo strategija" 
  },
  "lessonStages": { 
    "introduction": "Sužadinimas, tikslų kėlimas", 
    "theory": "Mokymosi medžiaga, DI/Skaitmeninių įrankių (pvz. Miro, Canva) naudojimas", 
    "practice": "Aktyvaus mokymosi veiklos", 
    "consolidation": "Žinių pasitikrinimas", 
    "summary": "Refleksija ir grįžtamasis ryšys" 
  },
  "differentiation": { "gifted": "Užduotys aukštesniam lygiui", "general": "Pagrindinis lygis", "struggling": "Sustiprinta pagalba/pastoliavimas" },
  "homework": { "purpose": "Tikslas", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Tema: ...\\nKlasės darbas: ...\\nLaukiami rezultatai: ...",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Integracija arba skaitmeninių priemonių panaudojimas (pvz. Classroom, Miro)",
  "consultationAdvice": "Sunkumų numatymas ir pagalba",
  "motivation": "Mokytojo palaikymo žinutė"
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);
    setIsEditingGeneratedPlan(false);

    const prompt = `
      Sukurk pamokos planą vadovaujantis LT BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Tipas: ${lessonType}
      - Tikslas: ${goal}
      - Papildomos veiklos: ${activities}
      - Vertinimas: ${evaluationType}
      - Naudoti įrankiai: Miro, Canva, Google Classroom (jei tinkama temai)
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Išvyka: ${isOutsideInput ? locationDetails : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("DI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType,
      groundingUrls
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
    setIsEditingGeneratedPlan(false);
  };

  const handleUpdateGeneratedPlan = () => {
    if (!editedPlan) return;
    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? { ...p, plan: editedPlan, title: editedPlan.lessonOverview.topic } : p));
    }
    setLessonPlan(editedPlan);
    setIsEditingGeneratedPlan(false);
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setIsEditingGeneratedPlan(false);
      setSubject(p.subject || '');
      setGrade(p.grade || '');
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = { ...editedPlan };
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const currentPlan = isEditingGeneratedPlan ? editedPlan : lessonPlan;

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>
          <a href="https://www.e-tar.lt/portal/lt/legalAct/e3e9269009e511ea9d279ea27696ab7b/asr" target="_blank" rel="noopener noreferrer" className="header-link">
            Griežtai vadovaujantis Lietuvos Bendrosiomis programomis
          </a>
        </p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai:</h3>
              <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones/priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Skaitmeninės priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai:</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>

            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>

            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>

            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>

            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(tag => <option key={tag} value={tag}>{tag}</option>)}
              </select>
            </div>

            <div className="form-group checkbox-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                Ar tai integruota pamoka?
              </label>
              {isIntegratedInput && (
                <input 
                  type="text" 
                  value={integrationDetails} 
                  onChange={e => setIntegrationDetails(e.target.value)} 
                  placeholder="Su kokiu dalyku integruojama?" 
                  className="nested-input"
                />
              )}
            </div>

            <div className="form-group checkbox-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                Ar tai pamoka už mokyklos ribų?
              </label>
              {isOutsideInput && (
                <input 
                  type="text" 
                  value={locationDetails} 
                  onChange={e => setLocationDetails(e.target.value)} 
                  placeholder="Kur vyks pamoka?" 
                  className="nested-input"
                />
              )}
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>Generuojama pagal emokykla.lt standartus...</p>
              <p style={{fontSize: '0.8rem', marginTop: '10px'}}>Tai gali užtrukti iki 30 sekundžių</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !currentPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje. Sukursime loginę pamokos eigą nuo įvado iki apibendrinimo.</p>
              <p style={{marginTop: '10px'}}>DI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {currentPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                {!isEditingGeneratedPlan ? (
                  <>
                    <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                    <button onClick={() => setIsEditingGeneratedPlan(true)} className="external-link-button">Redaguoti ✏️</button>
                  </>
                ) : (
                  <>
                    <button onClick={handleUpdateGeneratedPlan} className="save-button" style={{backgroundColor: 'var(--success-color)'}}>Baigti ✅</button>
                    <button onClick={() => { setIsEditingGeneratedPlan(false); setEditedPlan(lessonPlan); }} className="cancel-edit-button">Atšaukti ❌</button>
                  </>
                )}
              </div>

              <div className="card grounding-card">
                <h3>📚 Sąsajos su BP ir Kompetencijomis</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.bpConnections} onChange={e => updateEditedField('bpConnections', e.target.value)} style={{minHeight: '120px'}} />
                ) : (
                  <p style={{whiteSpace: 'pre-wrap'}}>{currentPlan.bpConnections}</p>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga</h3>
                <div className="overview-grid">
                  <div className="overview-field">
                    <strong>Tema:</strong> 
                    {isEditingGeneratedPlan ? (
                      <input 
                        type="text" 
                        className="edit-input" 
                        value={editedPlan?.lessonOverview.topic} 
                        onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} 
                        style={{marginTop: '5px', width: '100%'}}
                      />
                    ) : (
                      <span> {currentPlan.lessonOverview.topic}</span>
                    )}
                  </div>
                  <div className="overview-field" style={{marginTop: '15px'}}>
                    <strong>Tikslas:</strong> 
                    {isEditingGeneratedPlan ? (
                      <textarea 
                        className="edit-textarea" 
                        value={editedPlan?.lessonOverview.goal} 
                        onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} 
                        style={{marginTop: '5px', width: '100%', minHeight: '80px'}}
                      />
                    ) : (
                      <p style={{marginTop: '5px'}}>{currentPlan.lessonOverview.goal}</p>
                    )}
                  </div>
                  <div className="overview-field" style={{marginTop: '15px'}}>
                    <strong>Kompetencijos:</strong> 
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={editedPlan?.lessonOverview.competencies} onChange={e => updateEditedField('lessonOverview.competencies', e.target.value)} style={{marginTop: '5px', width: '100%'}} />
                    ) : (
                      <p style={{marginTop: '5px'}}>{currentPlan.lessonOverview.competencies}</p>
                    )}
                  </div>
                </div>
              </div>

              <div className="card lesson-stages-card">
                <h3>🛤️ Pamokos eiga</h3>
                {Object.entries({
                  introduction: '🏁 Įvadas',
                  theory: '🎓 Teorija',
                  practice: '✍️ Praktika',
                  consolidation: '🧩 Įtvirtinimas',
                  summary: '🏁 Apibendrinimas'
                }).map(([id, label]) => (
                  <div key={id} className="stage-item">
                    <strong>{label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.lessonStages as any)?.[id]} onChange={e => updateEditedField(`lessonStages.${id}`, e.target.value)} />
                    ) : (
                      <p>{(currentPlan.lessonStages as any)?.[id]}</p>
                    )}
                  </div>
                ))}
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'individualHomework'].map(key => (
                  <div key={key} style={{marginBottom: '10px'}}>
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'N.D.' : 'Indiv. N.D.'}</label>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.eDiaryEntry as any)?.[key]} onChange={e => updateEditedField(`eDiaryEntry.${key}`, e.target.value)} />
                    ) : (
                      <div className="diary-field">
                        <span style={{whiteSpace: 'pre-wrap'}}>{(currentPlan.eDiaryEntry as any)?.[key] || '---'}</span>
                        <button onClick={() => handleCopy((currentPlan.eDiaryEntry as any)?.[key], key)} className="copy-button">Kopijuoti</button>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p>{currentPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Išsaugoti planą?</h2>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="save-button">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Tikrai trinti?</h2>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); }} className="save-button" style={{backgroundColor: 'var(--error-color)'}}>Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Ne</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  /* Dark Theme Colors */
  --primary-color: #3b82f6;
  --primary-color-dark: #2563eb;
  --primary-color-light: #1e293b;
  --primary-color-focus: rgba(59, 130, 246, 0.3);
  --secondary-color: #10b981;
  --secondary-color-dark: #059669;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --shadow-color: rgba(0, 0, 0, 0.4);
  --error-color: #ef4444;
  --success-color: #10b981;
  --warning-color: #f59e0b;
  --info-color: #8b5cf6;
  --white: #ffffff;

  /* Typography */
  --font-family: 'Inter', sans-serif;
  --spacing-lg: 1rem;
  --spacing-xl: 1.5rem;
  --border-radius-md: 8px;
  --border-radius-lg: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font-family);
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: var(--spacing-lg);
}

.header {
  text-align: center;
  margin-bottom: 2rem;
  padding: var(--spacing-xl);
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.header h1 { color: var(--heading-color); margin-bottom: 0.5rem; }
.header-link { color: var(--primary-color); text-decoration: underline; font-weight: 500; }
.header-link:hover { color: var(--primary-color-dark); }

.header-sections {
  display: flex;
  justify-content: space-around;
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  flex-wrap: wrap;
  gap: 20px;
}

.resource-links, .tool-links {
  display: flex;
  align-items: center;
  gap: 12px;
}

.resource-links h3, .tool-links h3 {
  font-size: 0.9rem;
  color: var(--text-color-light);
  margin-right: 5px;
}

.mini-link {
  color: var(--primary-color);
  text-decoration: none;
  font-size: 0.85rem;
  padding: 4px 8px;
  border-radius: 4px;
  background-color: rgba(59, 130, 246, 0.1);
  transition: background 0.2s;
}

.mini-link:hover { background-color: rgba(59, 130, 246, 0.2); }

.tool-button {
  padding: 6px 14px;
  border-radius: 6px;
  color: white;
  text-decoration: none;
  font-size: 0.85rem;
  font-weight: 600;
  transition: opacity 0.2s;
}

.tool-button.classroom { background-color: #1e8e3e; }
.tool-button.miro { background-color: #ffcc00; color: #000; }
.tool-button.canva { background-color: #00c4cc; }
.tool-button:hover { opacity: 0.8; }

.main-content {
  display: grid;
  grid-template-columns: 380px 1fr;
  gap: 2rem;
}

.form-container {
  background-color: var(--surface-color);
  padding: 1.5rem;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
  height: fit-content;
}

.form-container h2 {
  color: var(--heading-color);
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
  text-align: center;
}

.form-group { margin-bottom: 1.25rem; }
.form-group label { display: block; color: var(--heading-color); margin-bottom: 6px; font-weight: 500; font-size: 0.95rem; }
.form-group input, .form-group textarea, .form-group select {
  width: 100%;
  padding: 10px;
  border-radius: 6px;
  border: 1px solid var(--border-color);
  background: #0f172a;
  color: white;
  font-family: inherit;
  font-size: 0.9rem;
}

.form-group select { cursor: pointer; }

.checkbox-group { display: flex; flex-direction: column; gap: 8px; margin-top: 1rem; }
.checkbox-label { display: flex; align-items: center; gap: 10px; cursor: pointer; user-select: none; font-size: 0.9rem !important; }
.checkbox-label input { width: 18px; height: 18px; cursor: pointer; }

.nested-input { margin-top: 8px; background: #1a2333 !important; border-color: var(--primary-color) !important; }

.generate-button {
  width: 100%;
  padding: 12px;
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  color: white;
  border: none;
  border-radius: 8px;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  margin-top: 1rem;
  transition: transform 0.2s, box-shadow 0.2s;
}

.generate-button:hover { transform: translateY(-1px); box-shadow: 0 4px 12px rgba(59, 130, 246, 0.4); }

.results-container {
  background-color: var(--surface-color);
  padding: 2rem;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
  min-height: 600px;
}

.card {
  background: #1e293b;
  border-left: 4px solid var(--primary-color);
  padding: 1.25rem;
  margin-bottom: 1.25rem;
  border-radius: 0 8px 8px 0;
}

.card h3 { margin-bottom: 0.75rem; color: var(--heading-color); }

.diary-field {
  display: flex;
  justify-content: space-between;
  background: #0f172a;
  padding: 10px;
  border-radius: 6px;
  margin-top: 5px;
}

.copy-button {
  background: var(--primary-color);
  color: white;
  border: none;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 0.75rem;
  cursor: pointer;
}

.edit-input, .edit-textarea {
  width: 100%;
  padding: 8px;
  background: #0f172a;
  color: white;
  border: 1px solid var(--primary-color);
  border-radius: 4px;
}

.export-container {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}

.save-button { background: var(--success-color); color: white; border: none; padding: 8px 16px; border-radius: 6px; cursor: pointer; }

.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.8);
  display: flex; justify-content: center; align-items: center;
  z-index: 1000;
}

.modal-content {
  background: var(--surface-color);
  padding: 2rem;
  border-radius: 12px;
  text-align: center;
}

.modal-actions { display: flex; gap: 10px; margin-top: 20px; justify-content: center; }

@media (max-width: 900px) {
  .main-content { grid-template-columns: 1fr; }
}

.spinner {
  width: 20px; height: 20px;
  border: 2px solid rgba(255,255,255,0.3);
  border-top-color: white;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';
type SortOption = 'date' | 'subject' | 'grade';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [consultationChallenges, setConsultationChallenges] = useState('');

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [locationDetails, setLocationDetails] = useState('');

  const [evaluationType, setEvaluationType] = useState(EVALUATION_TAGS[0]);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [showOnboarding, setShowOnboarding] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);

  const [isEditingGeneratedPlan, setIsEditingGeneratedPlan] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('date');

  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [editSubject, setEditSubject] = useState('');
  const [editGrade, setEditGrade] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP) ir kompetencijas. 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba, griežtai vadovaujantis šiais šaltiniais:
1. BP (Bendrosios programos): https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos
2. Skaitmeninės priemonės: https://emokykla.lt/skaitmenines-mokymo-priemones/priemones
3. Kompetencijų aprašas: https://emokykla.lt/bendrosios-programos/kompetencijos

Privalai įtraukti specifines kompetencijas (pažinimo, skaitmeninę, kūrybiškumo, komunikavimo, kultūrinę, pilietiškumo, socialinę, emocinę ir sveikos gyvensenos).
Rengdamas eigą, naudokis ilgalaikių planų pavyzdžiais iš emokykla.lt.

SVARBU dėl "eDiaryEntry" formato: Visada naudok taškus vietoj dvitaškių prie antraščių.
Struktūra turi būti tiksliai tokia:
{
  "generalNotes": "Bendros pastabos mokytojui, remiantis BP rekomendacijomis",
  "lessonType": "Tipas",
  "bpConnections": "Išsamios sąsajos su BP pasiekimų sritimis ir mokymo turiniu",
  "lessonOverview": { 
    "topic": "Tikslus temos pavadinimas", 
    "goal": "Pamokos uždavinys suformuluotas pagal SMART kriterijus", 
    "competencies": "Konkrečios ugdomos kompetencijos iš LT programos", 
    "evaluation": "Formuojamojo/apibendrinamojo vertinimo strategija" 
  },
  "lessonStages": { 
    "introduction": "Sužadinimas, tikslų kėlimas", 
    "theory": "Mokymosi medžiaga, DI/Skaitmeninių įrankių (pvz. Miro, Canva) naudojimas", 
    "practice": "Aktyvaus mokymosi veiklos", 
    "consolidation": "Žinių pasitikrinimas", 
    "summary": "Refleksija ir grįžtamasis ryšys" 
  },
  "differentiation": { 
    "gifted": "Konkrečios užduotys aukštesniam lygiui", 
    "general": "Pagrindinis lygis visiems", 
    "struggling": "Sustiprinta pagalba/lengvesnės užduotys" 
  },
  "homework": { "purpose": "Tikslas", "gifted": "", "general": "", "struggling": "" },
  "eDiaryEntry": {
    "topicClassworkExpectations": "Tema. [pavadinimas]\\nKlasės darbas. [veiklos]\\nLaukiami rezultatai. [geba]",
    "homework": "...",
    "individualHomework": "...",
    "notes": "...",
    "isIntegrated": false,
    "isOutside": false,
    "eDiaryLessonType": "..."
  },
  "specialAdvice": "Integracija arba skaitmeninių priemonių panaudojimas (pvz. Classroom, Miro)",
  "consultationAdvice": "Sunkumų numatymas ir pagalba",
  "motivation": "Mokytojo palaikymo žinutė"
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          return JSON.parse(jsonMatch[0]);
        } catch (e2) {}
      }
      return null;
    }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);
    setIsEditingGeneratedPlan(false);

    const prompt = `
      Sukurk pamokos planą vadovaujantis LT BP:
      - Dalykas: ${subject}, Klasė: ${grade}
      - Tema: ${topic}
      - Tipas: ${lessonType}
      - Tikslas: ${goal}
      - Papildomos veiklos: ${activities}
      - Vertinimas: ${evaluationType}
      - Pasiūlyk diferencijuotas veiklas pagal gebėjimus (aukštesnysis, pagrindinis, patenkinamas)
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          tools: [{ googleSearch: {} }] 
        },
      });

      const parsedPlan = tryParseJSON(response.text || '');

      if (!parsedPlan) {
        throw new Error("DI sugeneravo netinkamą formatą. Bandykite dar kartą.");
      }

      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const urls: {title: string, uri: string}[] = [];
      chunks.forEach((chunk: any) => {
        if (chunk.web) {
          urls.push({ title: chunk.web.title, uri: chunk.web.uri });
        }
      });
      setGroundingUrls(urls);

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType,
      groundingUrls
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
    setIsEditingGeneratedPlan(false);
  };

  const handleUpdateGeneratedPlan = () => {
    if (!editedPlan) return;
    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? { ...p, plan: editedPlan, title: editedPlan.lessonOverview.topic } : p));
    }
    setLessonPlan(editedPlan);
    setIsEditingGeneratedPlan(false);
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setIsEditingGeneratedPlan(false);
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = { ...editedPlan };
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const currentPlan = isEditingGeneratedPlan ? editedPlan : lessonPlan;

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>
          <a href="https://www.e-tar.lt/portal/lt/legalAct/e3e9269009e511ea9d279ea27696ab7b/asr" target="_blank" rel="noopener noreferrer" className="header-link">
            Griežtai vadovaujantis Lietuvos Bendrosiomis programomis
          </a>
        </p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai:</h3>
              <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones/priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Skaitmeninės priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai:</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžio laikai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti veiksmažodžio laikus..." />
            </div>
            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., darbas grupėse, interaktyvus žaidimas..." />
            </div>
            <div className="form-group">
              <label>Vertinimas</label>
              <select value={evaluationType} onChange={e => setEvaluationType(e.target.value)}>
                {EVALUATION_TAGS.map(tag => <option key={tag} value={tag}>{tag}</option>)}
              </select>
            </div>

            <div className="form-group checkbox-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                Ar tai integruota pamoka?
              </label>
              {isIntegratedInput && (
                <input 
                  type="text" 
                  value={integrationDetails} 
                  onChange={e => setIntegrationDetails(e.target.value)} 
                  placeholder="Su kokiu dalyku integruojama?" 
                  className="nested-input"
                />
              )}
            </div>

            <div className="form-group checkbox-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                Ar tai pamoka už mokyklos ribų?
              </label>
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? <div className="spinner"></div> : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>Generuojama pagal emokykla.lt standartus...</p>
              <p style={{fontSize: '0.8rem', marginTop: '10px'}}>Tai gali užtrukti iki 30 sekundžių</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !currentPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite formą kairėje. Sukursime loginę pamokos eigą nuo įvado iki apibendrinimo.</p>
              <p style={{marginTop: '10px'}}>DI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {currentPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                {!isEditingGeneratedPlan ? (
                  <>
                    <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                    <button onClick={() => setIsEditingGeneratedPlan(true)} className="external-link-button">Redaguoti ✏️</button>
                  </>
                ) : (
                  <>
                    <button onClick={handleUpdateGeneratedPlan} className="save-button" style={{backgroundColor: 'var(--success-color)'}}>Baigti ✅</button>
                    <button onClick={() => { setIsEditingGeneratedPlan(false); setEditedPlan(lessonPlan); }} className="cancel-edit-button">Atšaukti ❌</button>
                  </>
                )}
              </div>

              <div className="card grounding-card">
                <h3>📚 Sąsajos su BP ir Kompetencijomis</h3>
                {isEditingGeneratedPlan ? (
                  <textarea className="edit-textarea" value={editedPlan?.bpConnections} onChange={e => updateEditedField('bpConnections', e.target.value)} style={{minHeight: '120px'}} />
                ) : (
                  <p style={{whiteSpace: 'pre-wrap'}}>{currentPlan.bpConnections}</p>
                )}
              </div>

              <div className="card lesson-overview-card">
                <h3>📖 Apžvalga</h3>
                <div className="overview-grid">
                  <div className="overview-field">
                    <strong>Tema:</strong> 
                    {isEditingGeneratedPlan ? (
                      <input 
                        type="text" 
                        className="edit-input" 
                        value={editedPlan?.lessonOverview.topic} 
                        onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} 
                        style={{marginTop: '5px', width: '100%'}}
                      />
                    ) : (
                      <span> {currentPlan.lessonOverview.topic}</span>
                    )}
                  </div>
                  <div className="overview-field" style={{marginTop: '15px'}}>
                    <strong>Tikslas:</strong> 
                    {isEditingGeneratedPlan ? (
                      <textarea 
                        className="edit-textarea" 
                        value={editedPlan?.lessonOverview.goal} 
                        onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} 
                        style={{marginTop: '5px', width: '100%', minHeight: '80px'}}
                      />
                    ) : (
                      <p style={{marginTop: '5px'}}>{currentPlan.lessonOverview.goal}</p>
                    )}
                  </div>
                </div>
              </div>

              <div className="card differentiation-card">
                <h3>⚖️ Diferencijuotos veiklos</h3>
                {['gifted', 'general', 'struggling'].map(level => (
                  <div key={level} style={{marginBottom: '10px'}}>
                    <strong style={{textTransform: 'capitalize'}}>{level === 'gifted' ? '🚀 Aukštesnysis' : level === 'general' ? '🏠 Pagrindinis' : '🌱 Patenkinamas'}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.differentiation as any)?.[level]} onChange={e => updateEditedField(`differentiation.${level}`, e.target.value)} />
                    ) : (
                      <p>{(currentPlan.differentiation as any)?.[level]}</p>
                    )}
                  </div>
                ))}
              </div>

              <div className="card lesson-stages-card">
                <h3>🛤️ Pamokos eiga</h3>
                {Object.entries({
                  introduction: '🏁 Įvadas',
                  theory: '🎓 Teorija',
                  practice: '✍️ Praktika',
                  consolidation: '🧩 Įtvirtinimas',
                  summary: '🏁 Apibendrinimas'
                }).map(([id, label]) => (
                  <div key={id} className="stage-item">
                    <strong>{label}:</strong>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.lessonStages as any)?.[id]} onChange={e => updateEditedField(`lessonStages.${id}`, e.target.value)} />
                    ) : (
                      <p>{(currentPlan.lessonStages as any)?.[id]}</p>
                    )}
                  </div>
                ))}
              </div>

              <div className="card ediary-card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'individualHomework'].map(key => (
                  <div key={key} style={{marginBottom: '10px'}}>
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'N.D.' : 'Indiv. N.D.'}</label>
                    {isEditingGeneratedPlan ? (
                      <textarea className="edit-textarea" value={(editedPlan?.eDiaryEntry as any)?.[key]} onChange={e => updateEditedField(`eDiaryEntry.${key}`, e.target.value)} />
                    ) : (
                      <div className="diary-field">
                        <span style={{whiteSpace: 'pre-wrap'}}>{(currentPlan.eDiaryEntry as any)?.[key] || '---'}</span>
                        <button onClick={() => handleCopy((currentPlan.eDiaryEntry as any)?.[key], key)} className="copy-button">Kopijuoti</button>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="card motivation-card">
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p>{currentPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Išsaugoti planą?</h2>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="save-button">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="cancel-edit-button">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>Tikrai trinti?</h2>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); }} className="save-button" style={{backgroundColor: 'var(--error-color)'}}>Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="cancel-edit-button">Ne</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

