import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';
type SortOption = 'date' | 'subject' | 'grade';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface EvaluationData {
  methods: string[];
  criteria: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: EvaluationData;
  };
  tasks: {
    general: string;
    highLevel: string;
    mainLevel: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [evaluationCriteria, setEvaluationCriteria] = useState('');
  const [selectedEvaluations, setSelectedEvaluations] = useState<string[]>([]);

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  // Modal states
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP) ir kompetencijas. 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba, griežtai vadovaujantis BP ir emokykla.lt standartais.

SVARBU: Visada naudok taškus vietoj dvitaškių prie antraščių el. dienyno įrašuose.
Struktūra:
{
  "generalNotes": "...",
  "lessonType": "...",
  "bpConnections": "...",
  "lessonOverview": { "topic": "...", "goal": "...", "competencies": "...", "evaluation": { "methods": [], "criteria": "..." } },
  "tasks": { "general": "...", "highLevel": "...", "mainLevel": "..." },
  "lessonStages": { "introduction": "...", "theory": "...", "practice": "...", "consolidation": "...", "summary": "..." },
  "differentiation": { "gifted": "...", "general": "...", "struggling": "..." },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": { "topicClassworkExpectations": "...", "homework": "...", "individualHomework": "...", "notes": "...", "isIntegrated": false, "isOutside": false, "eDiaryLessonType": "..." },
  "specialAdvice": "...",
  "consultationAdvice": "...",
  "motivation": "..."
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { return JSON.parse(jsonMatch[0]); } catch (e2) {}
      }
      return null;
    }
  };

  const handleEvaluationToggle = (tag: string) => {
    setSelectedEvaluations(prev => 
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);
    setShowEditModal(false);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}, Tema: ${topic}
      - Tipas: ${lessonType}, Tikslas: ${goal}, Veiklos: ${activities}
      - Vertinimo metodai: ${selectedEvaluations.join(', ')}
      - Vertinimo kriterijai: ${evaluationCriteria}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json", tools: [{ googleSearch: {} }] },
      });

      const parsedPlan = tryParseJSON(response.text || '');
      if (!parsedPlan) throw new Error("Nepavyko sugeneruoti plano formatu. Bandykite vėl.");

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);

      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType,
      groundingUrls
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
  };

  const handleApplyEdit = () => {
    if (!editedPlan) return;
    setLessonPlan(editedPlan);
    setShowEditModal(false);
    if (activePlanId) {
       executeSavePlan();
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setSubject(p.subject || '');
      setGrade(p.grade || '');
      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = JSON.parse(JSON.stringify(editedPlan));
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p className="header-subtitle">Pagal Lietuvos Bendrąsias ugdymo programas</p>
        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai:</h3>
              <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">BP</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones/priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Priemonės</a>
            </div>
            <div className="tool-links">
              <h3>🛠️ Įrankiai:</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="pvz., Lietuvių kalba" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžiai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (SMART)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} rows={3} />
            </div>

            <div className="form-group">
              <label>Vertinimo metodai</label>
              <div className="evaluation-tags-grid">
                {EVALUATION_TAGS.map(tag => (
                  <label key={tag} className={`tag-checkbox ${selectedEvaluations.includes(tag) ? 'checked' : ''}`}>
                    <input type="checkbox" checked={selectedEvaluations.includes(tag)} onChange={() => handleEvaluationToggle(tag)} />
                    {tag}
                  </label>
                ))}
              </div>
            </div>

            <div className="form-group">
              <label>Vertinimo kriterijai</label>
              <textarea value={evaluationCriteria} onChange={e => setEvaluationCriteria(e.target.value)} rows={3} />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? "Generuojama..." : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="mini-delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>DI kuria jūsų pamokos planą...</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && (
            <div className="welcome-message">
              <h2>Sveiki atvykę! 👋</h2>
              <p>Užpildykite kairėje esančią formą ir DI parengs išsamų pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                <button onClick={() => { setEditedPlan(lessonPlan); setShowEditModal(true); }} className="edit-modal-btn">Redaguoti ✏️</button>
              </div>

              <div className="card">
                <h3>📚 Sąsajos su BP</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
              </div>

              <div className="card">
                <h3>📖 Apžvalga</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation.methods.join(', ')}</p>
              </div>

              <div className="card">
                <h3>📝 Užduotys</h3>
                <p><strong>Bendros:</strong> {lessonPlan.tasks?.general}</p>
                <p><strong>Aukštesniam lygiui:</strong> {lessonPlan.tasks?.highLevel}</p>
              </div>

              <div className="card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'notes'].map(key => (
                  <div key={key} className="diary-field-wrapper">
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'Namų darbai' : 'Pastabos'}</label>
                    <div className="diary-field">
                      <span className="diary-text">{(lessonPlan.eDiaryEntry as any)[key]}</span>
                      <button onClick={() => handleCopy((lessonPlan.eDiaryEntry as any)[key], key)} className="copy-button">Kopijuoti</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>

      {/* MODALAI - UŽTIKRINTAS MATOMUMAS */}
      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Patvirtinkite išsaugojimą</h2>
            </div>
            <p className="modal-body-text">Ar norite išsaugoti šį pamokos planą į savo asmeninį sąrašą?</p>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="modal-btn confirm">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {showEditModal && editedPlan && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content large" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Redaguoti planą</h2>
            </div>
            <div className="modal-body scrollable">
              <div className="edit-group">
                <label>Tema</label>
                <input type="text" value={editedPlan.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} />
              </div>
              <div className="edit-group">
                <label>SMART Tikslas</label>
                <textarea value={editedPlan.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Bendros)</label>
                <textarea value={editedPlan.tasks.general} onChange={e => updateEditedField('tasks.general', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Tema ir darbas</label>
                <textarea value={editedPlan.eDiaryEntry.topicClassworkExpectations} onChange={e => updateEditedField('eDiaryEntry.topicClassworkExpectations', e.target.value)} rows={3} />
              </div>
            </div>
            <div className="modal-actions">
                <button onClick={handleApplyEdit} className="modal-btn confirm">Išsaugoti pakeitimus</button>
                <button onClick={() => setShowEditModal(false)} className="modal-btn cancel">Uždaryti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Pašalinti planą?</h2>
            </div>
            <p className="modal-body-text">Šio veiksmo atšaukti negalėsite. Ar tikrai norite trinti?</p>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); if (activePlanId === deletingPlanId) setLessonPlan(null); }} className="modal-btn delete">Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  --primary-color: #3b82f6;
  --secondary-color: #10b981;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --error-color: #ef4444;
  --success-color: #10b981;
  --info-color: #8b5cf6;

  --spacing-md: 1rem;
  --border-radius-lg: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
}

.container { max-width: 1400px; margin: 0 auto; padding: var(--spacing-md); }

.header {
  text-align: center;
  margin-bottom: 2rem;
  padding: 1.5rem;
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.header h1 { color: var(--heading-color); margin-bottom: 0.25rem; }
.header-subtitle { font-size: 0.9rem; color: var(--primary-color); font-weight: 600; }

.header-sections {
  display: flex;
  justify-content: center;
  margin-top: 1rem;
  flex-wrap: wrap;
  gap: 1.5rem;
  border-top: 1px solid var(--border-color);
  padding-top: 1rem;
}

.mini-link {
  color: var(--primary-color);
  text-decoration: none;
  font-size: 0.8rem;
  padding: 4px 8px;
  background: rgba(59, 130, 246, 0.1);
  border-radius: 4px;
}

.tool-button {
  padding: 6px 12px;
  border-radius: 6px;
  color: white;
  text-decoration: none;
  font-size: 0.8rem;
  font-weight: bold;
}
.tool-button.classroom { background: #1e8e3e; }
.tool-button.miro { background: #ffcc00; color: black; }

/* Main Grid */
.main-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 1024px) {
  .main-content { grid-template-columns: 380px 1fr; }
}

.form-container, .results-container {
  background-color: var(--surface-color);
  padding: 1.5rem;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

/* Forms */
.form-group { margin-bottom: 1.2rem; }
.form-group label { display: block; color: var(--heading-color); margin-bottom: 6px; font-weight: 500; font-size: 0.9rem; }
.form-group input, .form-group textarea, .form-group select {
  width: 100%;
  padding: 10px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: #0f172a;
  color: white;
  font-size: 0.95rem;
}

.evaluation-tags-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tag-checkbox {
  padding: 6px;
  background: #0f172a;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  font-size: 0.75rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
}

.tag-checkbox.checked { border-color: var(--primary-color); color: var(--primary-color); }

.generate-button {
  width: 100%;
  padding: 12px;
  background: var(--primary-color);
  color: white;
  border: none;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
}

/* Modal Implementation */
.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(5px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999; /* Labai aukštas z-index užtikrina matomumą */
  padding: 20px;
}

.modal-content {
  background: var(--surface-color);
  border: 2px solid var(--primary-color);
  border-radius: 16px;
  width: 100%;
  max-width: 500px;
  padding: 2rem;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
}

.modal-content.large { max-width: 800px; max-height: 90vh; }

.modal-header h2 { color: var(--heading-color); margin-bottom: 1rem; border-bottom: 1px solid var(--border-color); padding-bottom: 0.5rem; }

.modal-body-text { color: var(--text-color-light); margin-bottom: 2rem; }

.modal-body.scrollable { overflow-y: auto; padding-right: 10px; margin-bottom: 1.5rem; }

.modal-actions { display: flex; gap: 1rem; margin-top: auto; }

.modal-btn {
  flex: 1;
  padding: 12px;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
  border: none;
}

.modal-btn.confirm { background: var(--success-color); color: white; }
.modal-btn.cancel { background: #334155; color: white; }
.modal-btn.delete { background: var(--error-color); color: white; }

/* Edit Form inside Modal */
.edit-group { margin-bottom: 1rem; }
.edit-group label { display: block; color: var(--heading-color); margin-bottom: 4px; font-size: 0.85rem; }
.edit-group input, .edit-group textarea {
  width: 100%;
  padding: 10px;
  background: #0f172a;
  border: 1px solid var(--border-color);
  color: white;
  border-radius: 6px;
}

/* Plan Result Card */
.card {
  background: #1e293b;
  border-left: 4px solid var(--primary-color);
  padding: 1rem;
  margin-bottom: 1rem;
  border-radius: 4px 10px 10px 4px;
}

.card h3 { color: var(--heading-color); margin-bottom: 0.5rem; font-size: 1rem; }

.diary-field-wrapper { margin-bottom: 1rem; }
.diary-label { font-size: 0.75rem; color: var(--text-color); display: block; margin-bottom: 4px; }
.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background: #0f172a;
  padding: 10px;
  border-radius: 8px;
  gap: 1rem;
}
.diary-text { font-size: 0.9rem; flex: 1; white-space: pre-wrap; color: var(--text-color-light); }
.copy-button { background: var(--primary-color); color: white; border: none; padding: 4px 8px; border-radius: 4px; font-size: 0.7rem; cursor: pointer; }

.export-container { display: flex; gap: 10px; margin-bottom: 1rem; }
.save-button { background: var(--success-color); color: white; padding: 10px; border-radius: 8px; flex: 1; border: none; cursor: pointer; font-weight: bold; }
.edit-modal-btn { background: var(--info-color); color: white; padding: 10px; border-radius: 8px; flex: 1; border: none; cursor: pointer; font-weight: bold; }

/* Saved Plans Sidebar */
.saved-plans-container { margin-top: 2rem; border-top: 1px solid var(--border-color); padding-top: 1rem; }
.search-input { width: 100%; padding: 8px; background: #0f172a; border: 1px solid var(--border-color); border-radius: 6px; color: white; margin-bottom: 10px; }
.saved-plans-list { list-style: none; }
.saved-plans-list li {
  padding: 10px; background: rgba(15, 23, 42, 0.5); border-radius: 6px; margin-bottom: 6px; cursor: pointer;
  display: flex; justify-content: space-between; align-items: center; border: 1px solid transparent;
}
.saved-plans-list li.active { border-color: var(--primary-color); background: rgba(59, 130, 246, 0.1); }
.plan-title { font-size: 0.85rem; color: var(--text-color-light); font-weight: 500; }
.mini-delete-button { color: var(--error-color); background: none; border: none; cursor: pointer; font-size: 0.9rem; }

/* Spinner */
.loading-overlay { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 300px; }
.spinner-large { width: 40px; height: 40px; border: 4px solid rgba(59, 130, 246, 0.2); border-top-color: var(--primary-color); border-radius: 50%; animation: spin 1s linear infinite; margin-bottom: 1rem; }
@keyframes spin { to { transform: rotate(360deg); } }

.welcome-message { text-align: center; padding: 3rem 1rem; }

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';
type SortOption = 'date' | 'subject' | 'grade';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface EvaluationData {
  methods: string[];
  criteria: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: EvaluationData;
  };
  tasks: {
    general: string;
    highLevel: string;
    mainLevel: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
  groundingUrls?: {title: string, uri: string}[];
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [evaluationCriteria, setEvaluationCriteria] = useState('');
  const [selectedEvaluations, setSelectedEvaluations] = useState<string[]>([]);

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [groundingUrls, setGroundingUrls] = useState<{title: string, uri: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  // Modal states
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP) ir kompetencijas. 
Tavo užduotis - sukurti labai išsamų, struktūruotą pamokos planą JSON formatu lietuvių kalba, griežtai vadovaujantis BP ir emokykla.lt standartais.

SVARBU: El. dienyno įrašuose (eDiaryEntry) GRIEŽTAI DRAUDŽIAMA naudoti dvitaškius (:) prie pavadinimų. Naudok tik taškus (.).
Pvz.: "Tema. Lietuvių kalba ir literatūra", "Klasės darbas. Teksto analizė".

Struktūra:
{
  "generalNotes": "...",
  "lessonType": "...",
  "bpConnections": "...",
  "lessonOverview": { "topic": "...", "goal": "...", "competencies": "...", "evaluation": { "methods": [], "criteria": "..." } },
  "tasks": { "general": "...", "highLevel": "...", "mainLevel": "..." },
  "lessonStages": { "introduction": "...", "theory": "...", "practice": "...", "consolidation": "...", "summary": "..." },
  "differentiation": { "gifted": "...", "general": "...", "struggling": "..." },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": { "topicClassworkExpectations": "...", "homework": "...", "individualHomework": "...", "notes": "...", "isIntegrated": false, "isOutside": false, "eDiaryLessonType": "..." },
  "specialAdvice": "...",
  "consultationAdvice": "...",
  "motivation": "..."
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { return JSON.parse(jsonMatch[0]); } catch (e2) {}
      }
      return null;
    }
  };

  const handleEvaluationToggle = (tag: string) => {
    setSelectedEvaluations(prev => 
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGroundingUrls([]);
    setShowEditModal(false);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}, Tema: ${topic}
      - Tipas: ${lessonType}, Tikslas: ${goal}, Veiklos: ${activities}
      - Vertinimo metodai: ${selectedEvaluations.join(', ')}
      - Vertinimo kriterijai: ${evaluationCriteria}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json", tools: [{ googleSearch: {} }] },
      });

      const parsedPlan = tryParseJSON(response.text || '');
      if (!parsedPlan) throw new Error("Nepavyko sugeneruoti plano formatu. Bandykite vėl.");

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);

      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType,
      groundingUrls
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
  };

  const handleApplyEdit = () => {
    if (!editedPlan) return;
    setLessonPlan(editedPlan);
    setShowEditModal(false);
    if (activePlanId) {
       executeSavePlan();
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setGroundingUrls(p.groundingUrls || []);
      setActivePlanId(p.id);
      setSubject(p.subject || '');
      setGrade(p.grade || '');
      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = JSON.parse(JSON.stringify(editedPlan));
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p className="header-subtitle">Pagal Lietuvos Bendrąsias ugdymo programas</p>
        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai</h3>
              <a href="https://emokykla.lt/bendrosios-programos/visos-bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">BP</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones/priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Priemonės</a>
            </div>
            <div className="tool-links">
              <h3>🛠️ Įrankiai</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Pvz. Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžiai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (SMART)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} rows={3} />
            </div>

            <div className="form-group">
              <label>Vertinimo metodai</label>
              <div className="evaluation-tags-grid">
                {EVALUATION_TAGS.map(tag => (
                  <label key={tag} className={`tag-checkbox ${selectedEvaluations.includes(tag) ? 'checked' : ''}`}>
                    <input type="checkbox" checked={selectedEvaluations.includes(tag)} onChange={() => handleEvaluationToggle(tag)} />
                    {tag}
                  </label>
                ))}
              </div>
            </div>

            <div className="form-group">
              <label>Vertinimo kriterijai</label>
              <textarea value={evaluationCriteria} onChange={e => setEvaluationCriteria(e.target.value)} rows={3} />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? "Generuojama..." : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="mini-delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>DI kuria jūsų pamokos planą...</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && (
            <div className="welcome-message">
              <h2>Sveiki atvykę! 👋</h2>
              <p>Užpildykite kairėje esančią formą ir DI parengs išsamų pamokos planą.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                <button onClick={() => { setEditedPlan(lessonPlan); setShowEditModal(true); }} className="edit-modal-btn">Redaguoti ✏️</button>
              </div>

              <div className="card">
                <h3>📚 Sąsajos su BP</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
              </div>

              <div className="card">
                <h3>📖 Apžvalga</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation.methods.join(', ')}</p>
              </div>

              <div className="card">
                <h3>📝 Užduotys</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                  <p><strong>Bendros:</strong> {lessonPlan.tasks?.general}</p>
                  <p><strong>Pagrindiniam lygiui:</strong> {lessonPlan.tasks?.mainLevel}</p>
                  <p><strong>Aukštesniam lygiui:</strong> {lessonPlan.tasks?.highLevel}</p>
                </div>
              </div>

              <div className="card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'notes'].map(key => (
                  <div key={key} className="diary-field-wrapper">
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'Namų darbai' : 'Pastabos'}</label>
                    <div className="diary-field">
                      <span className="diary-text">{(lessonPlan.eDiaryEntry as any)[key]}</span>
                      <button onClick={() => handleCopy((lessonPlan.eDiaryEntry as any)[key], key)} className="copy-button">Kopijuoti</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>

      {/* MODALAI */}
      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Patvirtinkite išsaugojimą</h2>
            </div>
            <p className="modal-body-text">Ar norite išsaugoti šį pamokos planą į savo asmeninį sąrašą?</p>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="modal-btn confirm">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {showEditModal && editedPlan && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content large" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Redaguoti planą</h2>
            </div>
            <div className="modal-body scrollable">
              <div className="edit-group">
                <label>Tema</label>
                <input type="text" value={editedPlan.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} />
              </div>
              <div className="edit-group">
                <label>SMART Tikslas</label>
                <textarea value={editedPlan.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Bendros)</label>
                <textarea value={editedPlan.tasks.general} onChange={e => updateEditedField('tasks.general', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Pagrindinis lygis)</label>
                <textarea value={editedPlan.tasks.mainLevel} onChange={e => updateEditedField('tasks.mainLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Aukštesnis lygis)</label>
                <textarea value={editedPlan.tasks.highLevel} onChange={e => updateEditedField('tasks.highLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Tema ir darbas</label>
                <textarea value={editedPlan.eDiaryEntry.topicClassworkExpectations} onChange={e => updateEditedField('eDiaryEntry.topicClassworkExpectations', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Pastabos</label>
                <textarea value={editedPlan.eDiaryEntry.notes} onChange={e => updateEditedField('eDiaryEntry.notes', e.target.value)} rows={3} />
              </div>
            </div>
            <div className="modal-actions">
                <button onClick={handleApplyEdit} className="modal-btn confirm">Išsaugoti pakeitimus</button>
                <button onClick={() => setShowEditModal(false)} className="modal-btn cancel">Uždaryti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Pašalinti planą?</h2>
            </div>
            <p className="modal-body-text">Šio veiksmo atšaukti negalėsite. Ar tikrai norite trinti?</p>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); if (activePlanId === deletingPlanId) setLessonPlan(null); }} className="modal-btn delete">Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface EvaluationData {
  methods: string[];
  criteria: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: EvaluationData;
  };
  tasks: {
    general: string;
    highLevel: string;
    mainLevel: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [evaluationCriteria, setEvaluationCriteria] = useState('');
  const [selectedEvaluations, setSelectedEvaluations] = useState<string[]>([]);

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  // Modal states
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP).
SVARBU: El. dienyno įrašuose (eDiaryEntry) GRIEŽTAI DRAUDŽIAMA naudoti dvitaškius (:) prie pavadinimų. Naudok tik taškus (.).
Pvz.: "Tema. Lietuvių kalba ir literatūra", "Klasės darbas. Teksto analizė".

Struktūra:
{
  "generalNotes": "...",
  "lessonType": "...",
  "bpConnections": "...",
  "lessonOverview": { "topic": "...", "goal": "...", "competencies": "...", "evaluation": { "methods": [], "criteria": "..." } },
  "tasks": { "general": "...", "highLevel": "...", "mainLevel": "..." },
  "lessonStages": { "introduction": "...", "theory": "...", "practice": "...", "consolidation": "...", "summary": "..." },
  "differentiation": { "gifted": "...", "general": "...", "struggling": "..." },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": { "topicClassworkExpectations": "...", "homework": "...", "individualHomework": "...", "notes": "...", "isIntegrated": false, "isOutside": false, "eDiaryLessonType": "..." },
  "specialAdvice": "...",
  "consultationAdvice": "...",
  "motivation": "..."
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { return JSON.parse(jsonMatch[0]); } catch (e2) {}
      }
      return null;
    }
  };

  const handleEvaluationToggle = (tag: string) => {
    setSelectedEvaluations(prev => 
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setShowEditModal(false);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}, Tema: ${topic}
      - Tipas: ${lessonType}, Tikslas: ${goal}, Veiklos: ${activities}
      - Vertinimo metodai: ${selectedEvaluations.join(', ')}
      - Vertinimo kriterijai: ${evaluationCriteria}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan = tryParseJSON(response.text || '');
      if (!parsedPlan) throw new Error("Nepavyko sugeneruoti plano formatu. Bandykite vėl.");

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);

      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
  };

  const handleApplyEdit = () => {
    if (!editedPlan) return;
    setLessonPlan(editedPlan);
    setShowEditModal(false);
    if (activePlanId) {
       executeSavePlan();
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setActivePlanId(p.id);
      setSubject(p.subject || '');
      setGrade(p.grade || '');
      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = JSON.parse(JSON.stringify(editedPlan));
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>
          <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="header-link">
            Griežtai vadovaujantis Lietuvos Bendrosiomis programomis
          </a>
        </p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai</h3>
              <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Pvz. Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžiai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti..." rows={3} />
            </div>
            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., žaidimai..." rows={2} />
            </div>

            <div className="form-group">
              <label>Vertinimo metodai (pasirinkite kelis)</label>
              <div className="evaluation-tags-grid">
                {EVALUATION_TAGS.map(tag => (
                  <label key={tag} className={`tag-checkbox ${selectedEvaluations.includes(tag) ? 'checked' : ''}`}>
                    <input type="checkbox" checked={selectedEvaluations.includes(tag)} onChange={() => handleEvaluationToggle(tag)} />
                    {tag}
                  </label>
                ))}
              </div>
            </div>

            <div className="form-group">
              <label>Vertinimo kriterijai</label>
              <textarea value={evaluationCriteria} onChange={e => setEvaluationCriteria(e.target.value)} placeholder="Aprašykite vertinimo kriterijus..." rows={3} />
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? "Generuojama..." : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti planuose..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="mini-delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>DI kuria jūsų pamokos planą...</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite duomenis kairėje ir spauskite „Generuoti planą“.</p>
              <p style={{marginTop: '15px', opacity: 0.8}}>DI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                <button onClick={() => { setEditedPlan(lessonPlan); setShowEditModal(true); }} className="edit-modal-btn">Redaguoti ✏️</button>
              </div>

              <div className="card">
                <h3>📚 Sąsajos su BP</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
              </div>

              <div className="card">
                <h3>📖 Apžvalga</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation.methods.join(', ')}</p>
              </div>

              <div className="card">
                <h3>📝 Užduotys</h3>
                <p><strong>Bendros:</strong> {lessonPlan.tasks?.general}</p>
                <p><strong>Pagrindiniam lygiui:</strong> {lessonPlan.tasks?.mainLevel}</p>
                <p><strong>Aukštesniam lygiui:</strong> {lessonPlan.tasks?.highLevel}</p>
              </div>

              <div className="card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'notes'].map(key => (
                  <div key={key} className="diary-field-wrapper">
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'Namų darbai' : 'Pastabos'}</label>
                    <div className="diary-field">
                      <span className="diary-text">{(lessonPlan.eDiaryEntry as any)[key]}</span>
                      <button onClick={() => handleCopy((lessonPlan.eDiaryEntry as any)[key], key)} className="copy-button">Kopijuoti</button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card" style={{borderLeftColor: 'var(--secondary-color)'}}>
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p style={{fontStyle: 'italic'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* MODALAI */}
      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Patvirtinkite išsaugojimą</h2>
            </div>
            <p className="modal-body-text">Ar norite išsaugoti šį pamokos planą į savo asmeninį sąrašą?</p>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="modal-btn confirm">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {showEditModal && editedPlan && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content large" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Redaguoti planą</h2>
            </div>
            <div className="modal-body scrollable">
              <div className="edit-group">
                <label>Tema</label>
                <input type="text" value={editedPlan.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} />
              </div>
              <div className="edit-group">
                <label>SMART Tikslas</label>
                <textarea value={editedPlan.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Bendros)</label>
                <textarea value={editedPlan.tasks.general} onChange={e => updateEditedField('tasks.general', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Pagrindinis lygis)</label>
                <textarea value={editedPlan.tasks.mainLevel} onChange={e => updateEditedField('tasks.mainLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Aukštesnis lygis)</label>
                <textarea value={editedPlan.tasks.highLevel} onChange={e => updateEditedField('tasks.highLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Tema ir darbas</label>
                <textarea value={editedPlan.eDiaryEntry.topicClassworkExpectations} onChange={e => updateEditedField('eDiaryEntry.topicClassworkExpectations', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Pastabos</label>
                <textarea value={editedPlan.eDiaryEntry.notes} onChange={e => updateEditedField('eDiaryEntry.notes', e.target.value)} rows={3} />
              </div>
            </div>
            <div className="modal-actions">
                <button onClick={handleApplyEdit} className="modal-btn confirm">Išsaugoti pakeitimus</button>
                <button onClick={() => setShowEditModal(false)} className="modal-btn cancel">Uždaryti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Pašalinti planą?</h2>
            </div>
            <p className="modal-body-text">Šio veiksmo atšaukti negalėsite. Ar tikrai norite trinti?</p>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); if (activePlanId === deletingPlanId) setLessonPlan(null); }} className="modal-btn delete">Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  --primary-color: #3b82f6;
  --secondary-color: #10b981;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --error-color: #ef4444;
  --success-color: #10b981;
  --info-color: #8b5cf6;

  --spacing-md: 1rem;
  --border-radius-lg: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container { max-width: 1400px; margin: 0 auto; padding: var(--spacing-md); }

.header {
  text-align: center;
  margin-bottom: 2rem;
  padding: 1.5rem;
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.header h1 { color: var(--heading-color); margin-bottom: 0.25rem; }
.header-link { color: var(--primary-color); text-decoration: none; font-size: 0.9rem; font-weight: 600; }

.header-sections {
  display: flex;
  justify-content: center;
  margin-top: 1rem;
  flex-wrap: wrap;
  gap: 1.5rem;
  border-top: 1px solid var(--border-color);
  padding-top: 1.2rem;
}

.resource-links, .tool-links {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.resource-links h3, .tool-links h3 {
  font-size: 0.85rem;
  color: var(--text-color-light);
  margin-right: 4px;
}

.mini-link {
  color: var(--primary-color);
  text-decoration: none;
  font-size: 0.8rem;
  padding: 4px 10px;
  background: rgba(59, 130, 246, 0.1);
  border-radius: 6px;
  border: 1px solid rgba(59, 130, 246, 0.2);
}

.tool-button {
  padding: 6px 14px;
  border-radius: 8px;
  color: white;
  text-decoration: none;
  font-size: 0.8rem;
  font-weight: bold;
}
.tool-button.classroom { background: #1e8e3e; }
.tool-button.miro { background: #ffcc00; color: black; }
.tool-button.canva { background: #00c4cc; }

/* Main Grid */
.main-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 1024px) {
  .main-content { grid-template-columns: 380px 1fr; }
}

.form-container, .results-container {
  background-color: var(--surface-color);
  padding: 1.5rem;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.form-container h2 { color: var(--heading-color); margin-bottom: 1.5rem; font-size: 1.25rem; }

/* Forms */
.form-group { margin-bottom: 1.2rem; }
.form-group label { display: block; color: var(--heading-color); margin-bottom: 8px; font-weight: 500; font-size: 0.9rem; }
.form-group input, .form-group textarea, .form-group select {
  width: 100%;
  padding: 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: #0f172a;
  color: white;
  font-size: 0.95rem;
  font-family: inherit;
}

.evaluation-tags-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tag-checkbox {
  padding: 10px;
  background: #0f172a;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 0.75rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s;
}

.tag-checkbox.checked { border-color: var(--primary-color); background: rgba(59, 130, 246, 0.1); color: white; }

.generate-button {
  width: 100%;
  padding: 14px;
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  color: white;
  border: none;
  border-radius: 10px;
  font-weight: bold;
  font-size: 1rem;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(0,0,0,0.2);
  margin-top: 1rem;
}

/* Modals */
.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
}

.modal-content {
  background: var(--surface-color);
  border: 2px solid var(--primary-color);
  border-radius: 16px;
  width: 100%;
  max-width: 500px;
  padding: 2rem;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
}

.modal-content.large { max-width: 850px; max-height: 90vh; display: flex; flex-direction: column; }
.modal-body.scrollable { overflow-y: auto; flex: 1; margin: 1rem 0; padding-right: 1rem; }

.modal-header h2 { color: var(--heading-color); margin-bottom: 1rem; border-bottom: 1px solid var(--border-color); padding-bottom: 0.5rem; }
.modal-body-text { color: var(--text-color-light); margin-bottom: 2rem; text-align: center; }
.modal-actions { display: flex; gap: 1rem; }

.modal-btn {
  flex: 1;
  padding: 12px;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
  border: none;
  font-family: inherit;
}

.modal-btn.confirm { background: var(--success-color); color: white; }
.modal-btn.cancel { background: #334155; color: white; }
.modal-btn.delete { background: var(--error-color); color: white; }

/* Plan Result Card */
.lesson-plan-result {
  animation: fadeIn 0.4s ease-out;
}

.card {
  background: #1e293b;
  border-left: 4px solid var(--primary-color);
  padding: 1.2rem;
  margin-bottom: 1.5rem;
  border-radius: 4px 12px 12px 4px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.15);
}

.card h3 { color: var(--heading-color); margin-bottom: 0.8rem; font-size: 1.1rem; }

.diary-field-wrapper { margin-bottom: 1.2rem; }
.diary-label { font-size: 0.8rem; color: var(--primary-color); display: block; margin-bottom: 6px; font-weight: 600; }
.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background: #0f172a;
  padding: 12px;
  border-radius: 10px;
  gap: 1rem;
}
.diary-text { font-size: 0.95rem; flex: 1; white-space: pre-wrap; color: var(--text-color-light); }
.copy-button { background: var(--primary-color); color: white; border: none; padding: 6px 12px; border-radius: 6px; font-size: 0.75rem; cursor: pointer; font-weight: bold; }

.export-container { display: flex; gap: 12px; margin-bottom: 1.5rem; }
.save-button { background: var(--success-color); color: white; padding: 12px; border-radius: 10px; flex: 1; border: none; cursor: pointer; font-weight: bold; font-size: 0.95rem; }
.edit-modal-btn { background: var(--info-color); color: white; padding: 12px; border-radius: 10px; flex: 1; border: none; cursor: pointer; font-weight: bold; font-size: 0.95rem; }

/* Saved Plans Sidebar */
.saved-plans-container { margin-top: 2rem; border-top: 1px solid var(--border-color); padding-top: 1.5rem; }
.search-input { width: 100%; padding: 10px; background: #0f172a; border: 1px solid var(--border-color); border-radius: 8px; color: white; margin-bottom: 1rem; font-family: inherit; }
.saved-plans-list { list-style: none; max-height: 350px; overflow-y: auto; }
.saved-plans-list li {
  padding: 12px; background: rgba(15, 23, 42, 0.5); border-radius: 8px; margin-bottom: 8px; cursor: pointer;
  display: flex; justify-content: space-between; align-items: center; border: 1px solid transparent;
}
.saved-plans-list li.active { border-color: var(--primary-color); background: rgba(59, 130, 246, 0.1); }
.plan-title { font-size: 0.85rem; color: var(--text-color-light); font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 180px; }
.mini-delete-button { color: var(--error-color); background: none; border: none; cursor: pointer; font-size: 1rem; padding: 4px; }

/* States */
.loading-overlay { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 350px; }
.spinner-large { width: 45px; height: 45px; border: 4px solid rgba(59, 130, 246, 0.2); border-top-color: var(--primary-color); border-radius: 50%; animation: spin 1s linear infinite; margin-bottom: 1.2rem; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.welcome-message { text-align: center; padding: 4rem 1rem; }
.welcome-message h2 { color: var(--heading-color); margin-bottom: 0.8rem; }

/* Edit Inputs */
.edit-group { margin-bottom: 1.2rem; }
.edit-group label { display: block; color: var(--text-color-light); margin-bottom: 6px; font-size: 0.85rem; font-weight: 600; }
.edit-group input, .edit-group textarea {
  width: 100%; padding: 12px; background: #0f172a; border: 1px solid var(--border-color); color: white; border-radius: 8px; font-family: inherit; font-size: 0.95rem;
}

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface EvaluationData {
  methods: string[];
  criteria: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: EvaluationData;
  };
  tasks: {
    general: string;
    highLevel: string;
    mainLevel: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [evaluationCriteria, setEvaluationCriteria] = useState('');
  const [selectedEvaluations, setSelectedEvaluations] = useState<string[]>([]);

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  // Modal states
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP).
SVARBU: El. dienyno įrašuose (eDiaryEntry) GRIEŽTAI DRAUDŽIAMA naudoti dvitaškius (:) prie pavadinimų. Naudok tik taškus (.).
Pvz. "Tema. Lietuvių kalba ir literatūra", "Klasės darbas. Teksto analizė".

Struktūra:
{
  "generalNotes": "...",
  "lessonType": "...",
  "bpConnections": "...",
  "lessonOverview": { "topic": "...", "goal": "...", "competencies": "...", "evaluation": { "methods": [], "criteria": "..." } },
  "tasks": { "general": "...", "highLevel": "...", "mainLevel": "..." },
  "lessonStages": { "introduction": "...", "theory": "...", "practice": "...", "consolidation": "...", "summary": "..." },
  "differentiation": { "gifted": "...", "general": "...", "struggling": "..." },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": { "topicClassworkExpectations": "...", "homework": "...", "individualHomework": "...", "notes": "...", "isIntegrated": false, "isOutside": false, "eDiaryLessonType": "..." },
  "specialAdvice": "...",
  "consultationAdvice": "...",
  "motivation": "..."
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { return JSON.parse(jsonMatch[0]); } catch (e2) {}
      }
      return null;
    }
  };

  const handleEvaluationToggle = (tag: string) => {
    setSelectedEvaluations(prev => 
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setShowEditModal(false);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}, Tema: ${topic}
      - Tipas: ${lessonType}, Tikslas: ${goal}, Veiklos: ${activities}
      - Vertinimo metodai: ${selectedEvaluations.join(', ')}
      - Vertinimo kriterijai: ${evaluationCriteria}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Pamoka už mokyklos ribų: ${isOutsideInput ? 'Taip' : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan = tryParseJSON(response.text || '');
      if (!parsedPlan) throw new Error("Nepavyko sugeneruoti plano formatu. Bandykite vėl.");

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);

      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
  };

  const handleApplyEdit = () => {
    if (!editedPlan) return;
    setLessonPlan(editedPlan);
    setShowEditModal(false);
    if (activePlanId) {
       executeSavePlan();
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setActivePlanId(p.id);
      setSubject(p.subject || '');
      setGrade(p.grade || '');
      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = JSON.parse(JSON.stringify(editedPlan));
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>
          <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="header-link">
            Griežtai vadovaujantis Lietuvos Bendrosiomis programomis
          </a>
        </p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai</h3>
              <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Pvz. Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžiai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti..." rows={3} />
            </div>
            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., žaidimai..." rows={2} />
            </div>

            <div className="form-group">
              <label>Vertinimo metodai (pasirinkite kelis)</label>
              <div className="evaluation-tags-grid">
                {EVALUATION_TAGS.map(tag => (
                  <label key={tag} className={`tag-checkbox ${selectedEvaluations.includes(tag) ? 'checked' : ''}`}>
                    <input type="checkbox" checked={selectedEvaluations.includes(tag)} onChange={() => handleEvaluationToggle(tag)} />
                    {tag}
                  </label>
                ))}
              </div>
            </div>

            <div className="form-group">
              <label>Vertinimo kriterijai</label>
              <textarea value={evaluationCriteria} onChange={e => setEvaluationCriteria(e.target.value)} placeholder="Aprašykite vertinimo kriterijus..." rows={3} />
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                Integruota pamoka?
              </label>
              {isIntegratedInput && (
                <input 
                  type="text" 
                  value={integrationDetails} 
                  onChange={e => setIntegrationDetails(e.target.value)} 
                  placeholder="Su kuo?" 
                  style={{marginTop: '8px'}}
                />
              )}
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                Už mokyklos ribų?
              </label>
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? "Generuojama..." : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti planuose..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="mini-delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>DI kuria jūsų pamokos planą...</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite duomenis kairėje ir spauskite „Generuoti planą“.</p>
              <p style={{marginTop: '15px', opacity: 0.8}}>DI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                <button onClick={() => { setEditedPlan(lessonPlan); setShowEditModal(true); }} className="edit-modal-btn">Redaguoti ✏️</button>
              </div>

              <div className="card">
                <h3>📚 Sąsajos su BP</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
              </div>

              <div className="card">
                <h3>📖 Apžvalga</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation.methods.join(', ')}</p>
              </div>

              <div className="card">
                <h3>📝 Užduotys</h3>
                <p><strong>Bendros:</strong> {lessonPlan.tasks?.general}</p>
                <p><strong>Pagrindiniam lygiui:</strong> {lessonPlan.tasks?.mainLevel}</p>
                <p><strong>Aukštesniam lygiui:</strong> {lessonPlan.tasks?.highLevel}</p>
              </div>

              <div className="card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'notes'].map(key => (
                  <div key={key} className="diary-field-wrapper">
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'Namų darbai' : 'Pastabos'}</label>
                    <div className="diary-field">
                      <span className="diary-text">{(lessonPlan.eDiaryEntry as any)[key]}</span>
                      <button onClick={() => handleCopy((lessonPlan.eDiaryEntry as any)[key], key)} className="copy-button">Kopijuoti</button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card" style={{borderLeftColor: 'var(--secondary-color)'}}>
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p style={{fontStyle: 'italic'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* MODALAI */}
      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Patvirtinkite išsaugojimą</h2>
            </div>
            <p className="modal-body-text">Ar norite išsaugoti šį pamokos planą į savo asmeninį sąrašą?</p>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="modal-btn confirm">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {showEditModal && editedPlan && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content large" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Redaguoti planą</h2>
            </div>
            <div className="modal-body scrollable">
              <div className="edit-group">
                <label>Tema</label>
                <input type="text" value={editedPlan.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} />
              </div>
              <div className="edit-group">
                <label>SMART Tikslas</label>
                <textarea value={editedPlan.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Bendros)</label>
                <textarea value={editedPlan.tasks.general} onChange={e => updateEditedField('tasks.general', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Pagrindinis lygis)</label>
                <textarea value={editedPlan.tasks.mainLevel} onChange={e => updateEditedField('tasks.mainLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Aukštesnis lygis)</label>
                <textarea value={editedPlan.tasks.highLevel} onChange={e => updateEditedField('tasks.highLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Tema ir darbas</label>
                <textarea value={editedPlan.eDiaryEntry.topicClassworkExpectations} onChange={e => updateEditedField('eDiaryEntry.topicClassworkExpectations', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Pastabos</label>
                <textarea value={editedPlan.eDiaryEntry.notes} onChange={e => updateEditedField('eDiaryEntry.notes', e.target.value)} rows={3} />
              </div>
            </div>
            <div className="modal-actions">
                <button onClick={handleApplyEdit} className="modal-btn confirm">Išsaugoti pakeitimus</button>
                <button onClick={() => setShowEditModal(false)} className="modal-btn cancel">Uždaryti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Pašalinti planą?</h2>
            </div>
            <p className="modal-body-text">Šio veiksmo atšaukti negalėsite. Ar tikrai norite trinti?</p>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); if (activePlanId === deletingPlanId) setLessonPlan(null); }} className="modal-btn delete">Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  --primary-color: #3b82f6;
  --secondary-color: #10b981;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --error-color: #ef4444;
  --success-color: #10b981;
  --info-color: #8b5cf6;

  --spacing-md: 1rem;
  --border-radius-lg: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container { max-width: 1400px; margin: 0 auto; padding: var(--spacing-md); }

.header {
  text-align: center;
  margin-bottom: 2rem;
  padding: 1.5rem;
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.header h1 { color: var(--heading-color); margin-bottom: 0.25rem; }
.header-link { color: var(--primary-color); text-decoration: none; font-size: 0.9rem; font-weight: 600; }

.header-sections {
  display: flex;
  justify-content: center;
  margin-top: 1rem;
  flex-wrap: wrap;
  gap: 1.5rem;
  border-top: 1px solid var(--border-color);
  padding-top: 1.2rem;
}

.resource-links, .tool-links {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.resource-links h3, .tool-links h3 {
  font-size: 0.85rem;
  color: var(--text-color-light);
  margin-right: 4px;
}

.mini-link {
  color: var(--primary-color);
  text-decoration: none;
  font-size: 0.8rem;
  padding: 4px 10px;
  background: rgba(59, 130, 246, 0.1);
  border-radius: 6px;
  border: 1px solid rgba(59, 130, 246, 0.2);
}

.tool-button {
  padding: 6px 14px;
  border-radius: 8px;
  color: white;
  text-decoration: none;
  font-size: 0.8rem;
  font-weight: bold;
}
.tool-button.classroom { background: #1e8e3e; }
.tool-button.miro { background: #ffcc00; color: black; }
.tool-button.canva { background: #00c4cc; }

/* Main Grid */
.main-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 1024px) {
  .main-content { grid-template-columns: 380px 1fr; }
}

.form-container, .results-container {
  background-color: var(--surface-color);
  padding: 1.5rem;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.form-container h2 { color: var(--heading-color); margin-bottom: 1.5rem; font-size: 1.25rem; }

/* Forms */
.form-group { margin-bottom: 1.2rem; }
.form-group label { display: block; color: var(--heading-color); margin-bottom: 8px; font-weight: 500; font-size: 0.9rem; }
.form-group input, .form-group textarea, .form-group select {
  width: 100%;
  padding: 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: #0f172a;
  color: white;
  font-size: 0.95rem;
  font-family: inherit;
}

.evaluation-tags-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tag-checkbox {
  padding: 10px;
  background: #0f172a;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 0.75rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s;
}

.tag-checkbox.checked { border-color: var(--primary-color); background: rgba(59, 130, 246, 0.1); color: white; }

.checkbox-label {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  color: var(--heading-color);
  font-size: 0.9rem;
  font-weight: 500;
  margin-top: 10px;
}

.checkbox-label input[type="checkbox"] {
  width: 18px;
  height: 18px;
  cursor: pointer;
}

.generate-button {
  width: 100%;
  padding: 14px;
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  color: white;
  border: none;
  border-radius: 10px;
  font-weight: bold;
  font-size: 1rem;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(0,0,0,0.2);
  margin-top: 1rem;
}

/* Modals */
.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
}

.modal-content {
  background: var(--surface-color);
  border: 2px solid var(--primary-color);
  border-radius: 16px;
  width: 100%;
  max-width: 500px;
  padding: 2rem;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
}

.modal-content.large { max-width: 850px; max-height: 90vh; display: flex; flex-direction: column; }
.modal-body.scrollable { overflow-y: auto; flex: 1; margin: 1rem 0; padding-right: 1rem; }

.modal-header h2 { color: var(--heading-color); margin-bottom: 1rem; border-bottom: 1px solid var(--border-color); padding-bottom: 0.5rem; }
.modal-body-text { color: var(--text-color-light); margin-bottom: 2rem; text-align: center; }
.modal-actions { display: flex; gap: 1rem; }

.modal-btn {
  flex: 1;
  padding: 12px;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
  border: none;
  font-family: inherit;
}

.modal-btn.confirm { background: var(--success-color); color: white; }
.modal-btn.cancel { background: #334155; color: white; }
.modal-btn.delete { background: var(--error-color); color: white; }

/* Plan Result Card */
.lesson-plan-result {
  animation: fadeIn 0.4s ease-out;
}

.card {
  background: #1e293b;
  border-left: 4px solid var(--primary-color);
  padding: 1.2rem;
  margin-bottom: 1.5rem;
  border-radius: 4px 12px 12px 4px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.15);
}

.card h3 { color: var(--heading-color); margin-bottom: 0.8rem; font-size: 1.1rem; }

.diary-field-wrapper { margin-bottom: 1.2rem; }
.diary-label { font-size: 0.8rem; color: var(--primary-color); display: block; margin-bottom: 6px; font-weight: 600; }
.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background: #0f172a;
  padding: 12px;
  border-radius: 10px;
  gap: 1rem;
}
.diary-text { font-size: 0.95rem; flex: 1; white-space: pre-wrap; color: var(--text-color-light); }
.copy-button { background: var(--primary-color); color: white; border: none; padding: 6px 12px; border-radius: 6px; font-size: 0.75rem; cursor: pointer; font-weight: bold; }

.export-container { display: flex; gap: 12px; margin-bottom: 1.5rem; }
.save-button { background: var(--success-color); color: white; padding: 12px; border-radius: 10px; flex: 1; border: none; cursor: pointer; font-weight: bold; font-size: 0.95rem; }
.edit-modal-btn { background: var(--info-color); color: white; padding: 12px; border-radius: 10px; flex: 1; border: none; cursor: pointer; font-weight: bold; font-size: 0.95rem; }

/* Saved Plans Sidebar */
.saved-plans-container { margin-top: 2rem; border-top: 1px solid var(--border-color); padding-top: 1.5rem; }
.search-input { width: 100%; padding: 10px; background: #0f172a; border: 1px solid var(--border-color); border-radius: 8px; color: white; margin-bottom: 1rem; font-family: inherit; }
.saved-plans-list { list-style: none; max-height: 350px; overflow-y: auto; }
.saved-plans-list li {
  padding: 12px; background: rgba(15, 23, 42, 0.5); border-radius: 8px; margin-bottom: 8px; cursor: pointer;
  display: flex; justify-content: space-between; align-items: center; border: 1px solid transparent;
}
.saved-plans-list li.active { border-color: var(--primary-color); background: rgba(59, 130, 246, 0.1); }
.plan-title { font-size: 0.85rem; color: var(--text-color-light); font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 180px; }
.mini-delete-button { color: var(--error-color); background: none; border: none; cursor: pointer; font-size: 1rem; padding: 4px; }

/* States */
.loading-overlay { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 350px; }
.spinner-large { width: 45px; height: 45px; border: 4px solid rgba(59, 130, 246, 0.2); border-top-color: var(--primary-color); border-radius: 50%; animation: spin 1s linear infinite; margin-bottom: 1.2rem; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.welcome-message { text-align: center; padding: 4rem 1rem; }
.welcome-message h2 { color: var(--heading-color); margin-bottom: 0.8rem; }

/* Edit Inputs */
.edit-group { margin-bottom: 1.2rem; }
.edit-group label { display: block; color: var(--text-color-light); margin-bottom: 6px; font-size: 0.85rem; font-weight: 600; }
.edit-group input, .edit-group textarea {
  width: 100%; padding: 12px; background: #0f172a; border: 1px solid var(--border-color); color: white; border-radius: 8px; font-family: inherit; font-size: 0.95rem;
}

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface EvaluationData {
  methods: string[];
  criteria: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: EvaluationData;
  };
  tasks: {
    general: string;
    highLevel: string;
    mainLevel: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [evaluationCriteria, setEvaluationCriteria] = useState('');
  const [selectedEvaluations, setSelectedEvaluations] = useState<string[]>([]);

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  // Modal states
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP).
SVARBU: El. dienyno įrašuose (eDiaryEntry) GRIEŽTAI DRAUDŽIAMA naudoti dvitaškius (:) prie pavadinimų. Naudok tik taškus (.).
Pvz. "Tema. Lietuvių kalba ir literatūra", "Klasės darbas. Teksto analizė".

Jei pamoka vyksta „už mokyklos ribų“, orientuokis į patirtinį mokymąsi (experiential learning). 
Tokios pamokos tikslai turėtų būti: tyrinėjimas, realaus pasaulio stebėjimas, kultūrinio konteksto pažinimas arba praktinis žinių taikymas netradicinėje aplinkoje.

Struktūra:
{
  "generalNotes": "...",
  "lessonType": "...",
  "bpConnections": "...",
  "lessonOverview": { "topic": "...", "goal": "...", "competencies": "...", "evaluation": { "methods": [], "criteria": "..." } },
  "tasks": { "general": "...", "highLevel": "...", "mainLevel": "..." },
  "lessonStages": { "introduction": "...", "theory": "...", "practice": "...", "consolidation": "...", "summary": "..." },
  "differentiation": { "gifted": "...", "general": "...", "struggling": "..." },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": { "topicClassworkExpectations": "...", "homework": "...", "individualHomework": "...", "notes": "...", "isIntegrated": false, "isOutside": false, "eDiaryLessonType": "..." },
  "specialAdvice": "...",
  "consultationAdvice": "...",
  "motivation": "..."
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { return JSON.parse(jsonMatch[0]); } catch (e2) {}
      }
      return null;
    }
  };

  const handleEvaluationToggle = (tag: string) => {
    setSelectedEvaluations(prev => 
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setShowEditModal(false);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}, Tema: ${topic}
      - Tipas: ${lessonType}, Tikslas: ${goal}, Veiklos: ${activities}
      - Vertinimo metodai: ${selectedEvaluations.join(', ')}
      - Vertinimo kriterijai: ${evaluationCriteria}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Pamoka už mokyklos ribų: ${isOutsideInput ? 'Taip (akcentuok patirtinį mokymąsi, tyrinėjimą ir praktinį taikymą aplinkoje)' : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan = tryParseJSON(response.text || '');
      if (!parsedPlan) throw new Error("Nepavyko sugeneruoti plano formatu. Bandykite vėl.");

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);

      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
  };

  const handleApplyEdit = () => {
    if (!editedPlan) return;
    setLessonPlan(editedPlan);
    setShowEditModal(false);
    if (activePlanId) {
       executeSavePlan();
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setActivePlanId(p.id);
      setSubject(p.subject || '');
      setGrade(p.grade || '');
      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = JSON.parse(JSON.stringify(editedPlan));
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>
          <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="header-link">
            Griežtai vadovaujantis Lietuvos Bendrosiomis programomis
          </a>
        </p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai</h3>
              <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Pvz. Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžiai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti..." rows={3} />
            </div>
            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., žaidimai..." rows={2} />
            </div>

            <div className="form-group">
              <label>Vertinimo metodai (pasirinkite kelis)</label>
              <div className="evaluation-tags-grid">
                {EVALUATION_TAGS.map(tag => (
                  <label key={tag} className={`tag-checkbox ${selectedEvaluations.includes(tag) ? 'checked' : ''}`}>
                    <input type="checkbox" checked={selectedEvaluations.includes(tag)} onChange={() => handleEvaluationToggle(tag)} />
                    {tag}
                  </label>
                ))}
              </div>
            </div>

            <div className="form-group">
              <label>Vertinimo kriterijai</label>
              <textarea value={evaluationCriteria} onChange={e => setEvaluationCriteria(e.target.value)} placeholder="Aprašykite vertinimo kriterijus..." rows={3} />
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                Integruota pamoka?
              </label>
              {isIntegratedInput && (
                <input 
                  type="text" 
                  value={integrationDetails} 
                  onChange={e => setIntegrationDetails(e.target.value)} 
                  placeholder="Su kuo?" 
                  style={{marginTop: '8px'}}
                />
              )}
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                Už mokyklos ribų?
              </label>
              <p className="helper-text">Rekomenduojami tikslai: tyrinėjimas, stebėjimas, patirtinis mokymasis.</p>
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? "Generuojama..." : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti planuose..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="mini-delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>DI kuria jūsų pamokos planą...</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite duomenis kairėje ir spauskite „Generuoti planą“.</p>
              <p style={{marginTop: '15px', opacity: 0.8}}>DI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                <button onClick={() => { setEditedPlan(lessonPlan); setShowEditModal(true); }} className="edit-modal-btn">Redaguoti ✏️</button>
              </div>

              <div className="card">
                <h3>📚 Sąsajos su BP</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
              </div>

              <div className="card">
                <h3>📖 Apžvalga</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation.methods.join(', ')}</p>
              </div>

              <div className="card">
                <h3>📝 Užduotys</h3>
                <p><strong>Bendros:</strong> {lessonPlan.tasks?.general}</p>
                <p><strong>Pagrindiniam lygiui:</strong> {lessonPlan.tasks?.mainLevel}</p>
                <p><strong>Aukštesniam lygiui:</strong> {lessonPlan.tasks?.highLevel}</p>
              </div>

              <div className="card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'notes'].map(key => (
                  <div key={key} className="diary-field-wrapper">
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'Namų darbai' : 'Pastabos'}</label>
                    <div className="diary-field">
                      <span className="diary-text">{(lessonPlan.eDiaryEntry as any)[key]}</span>
                      <button onClick={() => handleCopy((lessonPlan.eDiaryEntry as any)[key], key)} className="copy-button">Kopijuoti</button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card" style={{borderLeftColor: 'var(--secondary-color)'}}>
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p style={{fontStyle: 'italic'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* MODALAI */}
      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Patvirtinkite išsaugojimą</h2>
            </div>
            <p className="modal-body-text">Ar norite išsaugoti šį pamokos planą į savo asmeninį sąrašą?</p>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="modal-btn confirm">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {showEditModal && editedPlan && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content large" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Redaguoti planą</h2>
            </div>
            <div className="modal-body scrollable">
              <div className="edit-group">
                <label>Tema</label>
                <input type="text" value={editedPlan.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} />
              </div>
              <div className="edit-group">
                <label>SMART Tikslas</label>
                <textarea value={editedPlan.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Bendros)</label>
                <textarea value={editedPlan.tasks.general} onChange={e => updateEditedField('tasks.general', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Pagrindinis lygis)</label>
                <textarea value={editedPlan.tasks.mainLevel} onChange={e => updateEditedField('tasks.mainLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Aukštesnis lygis)</label>
                <textarea value={editedPlan.tasks.highLevel} onChange={e => updateEditedField('tasks.highLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Tema ir darbas</label>
                <textarea value={editedPlan.eDiaryEntry.topicClassworkExpectations} onChange={e => updateEditedField('eDiaryEntry.topicClassworkExpectations', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Pastabos</label>
                <textarea value={editedPlan.eDiaryEntry.notes} onChange={e => updateEditedField('eDiaryEntry.notes', e.target.value)} rows={3} />
              </div>
            </div>
            <div className="modal-actions">
                <button onClick={handleApplyEdit} className="modal-btn confirm">Išsaugoti pakeitimus</button>
                <button onClick={() => setShowEditModal(false)} className="modal-btn cancel">Uždaryti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Pašalinti planą?</h2>
            </div>
            <p className="modal-body-text">Šio veiksmo atšaukti negalėsite. Ar tikrai norite trinti?</p>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); if (activePlanId === deletingPlanId) setLessonPlan(null); }} className="modal-btn delete">Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  --primary-color: #3b82f6;
  --secondary-color: #10b981;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --error-color: #ef4444;
  --success-color: #10b981;
  --info-color: #8b5cf6;

  --spacing-md: 1rem;
  --border-radius-lg: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container { max-width: 1400px; margin: 0 auto; padding: var(--spacing-md); }

.header {
  text-align: center;
  margin-bottom: 2rem;
  padding: 1.5rem;
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.header h1 { color: var(--heading-color); margin-bottom: 0.25rem; }
.header-link { color: var(--primary-color); text-decoration: none; font-size: 0.9rem; font-weight: 600; }

.header-sections {
  display: flex;
  justify-content: center;
  margin-top: 1rem;
  flex-wrap: wrap;
  gap: 1.5rem;
  border-top: 1px solid var(--border-color);
  padding-top: 1.2rem;
}

.resource-links, .tool-links {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.resource-links h3, .tool-links h3 {
  font-size: 0.85rem;
  color: var(--text-color-light);
  margin-right: 4px;
}

.mini-link {
  color: var(--primary-color);
  text-decoration: none;
  font-size: 0.8rem;
  padding: 4px 10px;
  background: rgba(59, 130, 246, 0.1);
  border-radius: 6px;
  border: 1px solid rgba(59, 130, 246, 0.2);
}

.tool-button {
  padding: 6px 14px;
  border-radius: 8px;
  color: white;
  text-decoration: none;
  font-size: 0.8rem;
  font-weight: bold;
}
.tool-button.classroom { background: #1e8e3e; }
.tool-button.miro { background: #ffcc00; color: black; }
.tool-button.canva { background: #00c4cc; }

/* Main Grid */
.main-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 1024px) {
  .main-content { grid-template-columns: 380px 1fr; }
}

.form-container, .results-container {
  background-color: var(--surface-color);
  padding: 1.5rem;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.form-container h2 { color: var(--heading-color); margin-bottom: 1.5rem; font-size: 1.25rem; }

/* Forms */
.form-group { margin-bottom: 1.2rem; }
.form-group label { display: block; color: var(--heading-color); margin-bottom: 8px; font-weight: 500; font-size: 0.9rem; }
.form-group input, .form-group textarea, .form-group select {
  width: 100%;
  padding: 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: #0f172a;
  color: white;
  font-size: 0.95rem;
  font-family: inherit;
}

.evaluation-tags-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tag-checkbox {
  padding: 10px;
  background: #0f172a;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 0.75rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s;
}

.tag-checkbox.checked { border-color: var(--primary-color); background: rgba(59, 130, 246, 0.1); color: white; }

.checkbox-label {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  color: var(--heading-color);
  font-size: 0.9rem;
  font-weight: 500;
  margin-top: 10px;
}

.checkbox-label input[type="checkbox"] {
  width: 18px;
  height: 18px;
  cursor: pointer;
}

.helper-text {
  font-size: 0.75rem;
  color: var(--text-color);
  margin-top: 4px;
  font-style: italic;
  padding-left: 28px;
}

.generate-button {
  width: 100%;
  padding: 14px;
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  color: white;
  border: none;
  border-radius: 10px;
  font-weight: bold;
  font-size: 1rem;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(0,0,0,0.2);
  margin-top: 1rem;
}

/* Modals */
.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
}

.modal-content {
  background: var(--surface-color);
  border: 2px solid var(--primary-color);
  border-radius: 16px;
  width: 100%;
  max-width: 500px;
  padding: 2rem;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
}

.modal-content.large { max-width: 850px; max-height: 90vh; display: flex; flex-direction: column; }
.modal-body.scrollable { overflow-y: auto; flex: 1; margin: 1rem 0; padding-right: 1rem; }

.modal-header h2 { color: var(--heading-color); margin-bottom: 1rem; border-bottom: 1px solid var(--border-color); padding-bottom: 0.5rem; }
.modal-body-text { color: var(--text-color-light); margin-bottom: 2rem; text-align: center; }
.modal-actions { display: flex; gap: 1rem; }

.modal-btn {
  flex: 1;
  padding: 12px;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
  border: none;
  font-family: inherit;
}

.modal-btn.confirm { background: var(--success-color); color: white; }
.modal-btn.cancel { background: #334155; color: white; }
.modal-btn.delete { background: var(--error-color); color: white; }

/* Plan Result Card */
.lesson-plan-result {
  animation: fadeIn 0.4s ease-out;
}

.card {
  background: #1e293b;
  border-left: 4px solid var(--primary-color);
  padding: 1.2rem;
  margin-bottom: 1.5rem;
  border-radius: 4px 12px 12px 4px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.15);
}

.card h3 { color: var(--heading-color); margin-bottom: 0.8rem; font-size: 1.1rem; }

.diary-field-wrapper { margin-bottom: 1.2rem; }
.diary-label { font-size: 0.8rem; color: var(--primary-color); display: block; margin-bottom: 6px; font-weight: 600; }
.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background: #0f172a;
  padding: 12px;
  border-radius: 10px;
  gap: 1rem;
}
.diary-text { font-size: 0.95rem; flex: 1; white-space: pre-wrap; color: var(--text-color-light); }
.copy-button { background: var(--primary-color); color: white; border: none; padding: 6px 12px; border-radius: 6px; font-size: 0.75rem; cursor: pointer; font-weight: bold; }

.export-container { display: flex; gap: 12px; margin-bottom: 1.5rem; }
.save-button { background: var(--success-color); color: white; padding: 12px; border-radius: 10px; flex: 1; border: none; cursor: pointer; font-weight: bold; font-size: 0.95rem; }
.edit-modal-btn { background: var(--info-color); color: white; padding: 12px; border-radius: 10px; flex: 1; border: none; cursor: pointer; font-weight: bold; font-size: 0.95rem; }

/* Saved Plans Sidebar */
.saved-plans-container { margin-top: 2rem; border-top: 1px solid var(--border-color); padding-top: 1.5rem; }
.search-input { width: 100%; padding: 10px; background: #0f172a; border: 1px solid var(--border-color); border-radius: 8px; color: white; margin-bottom: 1rem; font-family: inherit; }
.saved-plans-list { list-style: none; max-height: 350px; overflow-y: auto; }
.saved-plans-list li {
  padding: 12px; background: rgba(15, 23, 42, 0.5); border-radius: 8px; margin-bottom: 8px; cursor: pointer;
  display: flex; justify-content: space-between; align-items: center; border: 1px solid transparent;
}
.saved-plans-list li.active { border-color: var(--primary-color); background: rgba(59, 130, 246, 0.1); }
.plan-title { font-size: 0.85rem; color: var(--text-color-light); font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 180px; }
.mini-delete-button { color: var(--error-color); background: none; border: none; cursor: pointer; font-size: 1rem; padding: 4px; }

/* States */
.loading-overlay { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 350px; }
.spinner-large { width: 45px; height: 45px; border: 4px solid rgba(59, 130, 246, 0.2); border-top-color: var(--primary-color); border-radius: 50%; animation: spin 1s linear infinite; margin-bottom: 1.2rem; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.welcome-message { text-align: center; padding: 4rem 1rem; }
.welcome-message h2 { color: var(--heading-color); margin-bottom: 0.8rem; }

/* Edit Inputs */
.edit-group { margin-bottom: 1.2rem; }
.edit-group label { display: block; color: var(--text-color-light); margin-bottom: 6px; font-size: 0.85rem; font-weight: 600; }
.edit-group input, .edit-group textarea {
  width: 100%; padding: 12px; background: #0f172a; border: 1px solid var(--border-color); color: white; border-radius: 8px; font-family: inherit; font-size: 0.95rem;
}

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface EvaluationData {
  methods: string[];
  criteria: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: EvaluationData;
  };
  tasks: {
    general: string;
    highLevel: string;
    mainLevel: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [evaluationCriteria, setEvaluationCriteria] = useState('');
  const [selectedEvaluations, setSelectedEvaluations] = useState<string[]>([]);

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [outsideLocation, setOutsideLocation] = useState('');
  const [outsideGoal, setOutsideGoal] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  // Modal states
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP).
SVARBU: El. dienyno įrašuose (eDiaryEntry) GRIEŽTAI DRAUDŽIAMA naudoti dvitaškius (:) prie pavadinimų. Naudok tik taškus (.).
Pvz. "Tema. Lietuvių kalba ir literatūra", "Klasės darbas. Teksto analizė".

Jei pamoka vyksta „už mokyklos ribų“, orientuokis į patirtinį mokymąsi (experiential learning). 
Tokios pamokos tikslai turėtų būti: tyrinėjimas, realaus pasaulio stebėjimas, kultūrinio konteksto pažinimas arba praktinis žinių taikymas netradicinėje aplinkoje.

Struktūra:
{
  "generalNotes": "...",
  "lessonType": "...",
  "bpConnections": "...",
  "lessonOverview": { "topic": "...", "goal": "...", "competencies": "...", "evaluation": { "methods": [], "criteria": "..." } },
  "tasks": { "general": "...", "highLevel": "...", "mainLevel": "..." },
  "lessonStages": { "introduction": "...", "theory": "...", "practice": "...", "consolidation": "...", "summary": "..." },
  "differentiation": { "gifted": "...", "general": "...", "struggling": "..." },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": { "topicClassworkExpectations": "...", "homework": "...", "individualHomework": "...", "notes": "...", "isIntegrated": false, "isOutside": false, "eDiaryLessonType": "..." },
  "specialAdvice": "...",
  "consultationAdvice": "...",
  "motivation": "..."
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { return JSON.parse(jsonMatch[0]); } catch (e2) {}
      }
      return null;
    }
  };

  const handleEvaluationToggle = (tag: string) => {
    setSelectedEvaluations(prev => 
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setShowEditModal(false);

    const prompt = `
      Sukurk pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}, Tema: ${topic}
      - Tipas: ${lessonType}, Tikslas: ${goal}, Veiklos: ${activities}
      - Vertinimo metodai: ${selectedEvaluations.join(', ')}
      - Vertinimo kriterijai: ${evaluationCriteria}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Pamoka už mokyklos ribų: ${isOutsideInput ? `Taip. Vieta: ${outsideLocation}, Tikslas: ${outsideGoal}. Akcentuok patirtinį mokymąsi, tyrinėjimą ir praktinį taikymą šioje aplinkoje.` : 'Ne'}
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan = tryParseJSON(response.text || '');
      if (!parsedPlan) throw new Error("Nepavyko sugeneruoti plano formatu. Bandykite vėl.");

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);

      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
  };

  const handleApplyEdit = () => {
    if (!editedPlan) return;
    setLessonPlan(editedPlan);
    setShowEditModal(false);
    if (activePlanId) {
       executeSavePlan();
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setActivePlanId(p.id);
      setSubject(p.subject || '');
      setGrade(p.grade || '');
      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = JSON.parse(JSON.stringify(editedPlan));
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>
          <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="header-link">
            Griežtai vadovaujantis Lietuvos Bendrosiomis programomis
          </a>
        </p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai</h3>
              <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Pvz. Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžiai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti..." rows={3} />
            </div>
            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., žaidimai..." rows={2} />
            </div>

            <div className="form-group">
              <label>Vertinimo metodai (pasirinkite kelis)</label>
              <div className="evaluation-tags-grid">
                {EVALUATION_TAGS.map(tag => (
                  <label key={tag} className={`tag-checkbox ${selectedEvaluations.includes(tag) ? 'checked' : ''}`}>
                    <input type="checkbox" checked={selectedEvaluations.includes(tag)} onChange={() => handleEvaluationToggle(tag)} />
                    {tag}
                  </label>
                ))}
              </div>
            </div>

            <div className="form-group">
              <label>Vertinimo kriterijai</label>
              <textarea value={evaluationCriteria} onChange={e => setEvaluationCriteria(e.target.value)} placeholder="Aprašykite vertinimo kriterijus..." rows={3} />
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                Integruota pamoka?
              </label>
              {isIntegratedInput && (
                <input 
                  type="text" 
                  value={integrationDetails} 
                  onChange={e => setIntegrationDetails(e.target.value)} 
                  placeholder="Su kuo?" 
                  style={{marginTop: '8px'}}
                />
              )}
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                Už mokyklos ribų?
              </label>
              {isOutsideInput && (
                <div style={{marginTop: '10px', display: 'flex', flexDirection: 'column', gap: '8px'}}>
                  <input 
                    type="text" 
                    value={outsideLocation} 
                    onChange={e => setOutsideLocation(e.target.value)} 
                    placeholder="Kur? (pvz., Muziejus, parkas)" 
                  />
                  <input 
                    type="text" 
                    value={outsideGoal} 
                    onChange={e => setOutsideGoal(e.target.value)} 
                    placeholder="Kokiu ugdymo tikslu?" 
                  />
                  <p className="helper-text">Rekomenduojami tikslai: tyrinėjimas, stebėjimas, patirtinis mokymasis.</p>
                </div>
              )}
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? "Generuojama..." : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti planuose..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="mini-delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>DI kuria jūsų pamokos planą...</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite duomenis kairėje ir spauskite „Generuoti planą“.</p>
              <p style={{marginTop: '15px', opacity: 0.8}}>DI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                <button onClick={() => { setEditedPlan(lessonPlan); setShowEditModal(true); }} className="edit-modal-btn">Redaguoti ✏️</button>
              </div>

              <div className="card">
                <h3>📚 Sąsajos su BP</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
              </div>

              <div className="card">
                <h3>📖 Apžvalga</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation.methods.join(', ')}</p>
              </div>

              <div className="card">
                <h3>📝 Užduotys</h3>
                <p><strong>Bendros:</strong> {lessonPlan.tasks?.general}</p>
                <p><strong>Pagrindiniam lygiui:</strong> {lessonPlan.tasks?.mainLevel}</p>
                <p><strong>Aukštesniam lygiui:</strong> {lessonPlan.tasks?.highLevel}</p>
              </div>

              <div className="card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'notes'].map(key => (
                  <div key={key} className="diary-field-wrapper">
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'Namų darbai' : 'Pastabos'}</label>
                    <div className="diary-field">
                      <span className="diary-text">{(lessonPlan.eDiaryEntry as any)[key]}</span>
                      <button onClick={() => handleCopy((lessonPlan.eDiaryEntry as any)[key], key)} className="copy-button">Kopijuoti</button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card" style={{borderLeftColor: 'var(--secondary-color)'}}>
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p style={{fontStyle: 'italic'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* MODALAI */}
      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Patvirtinkite išsaugojimą</h2>
            </div>
            <p className="modal-body-text">Ar norite išsaugoti šį pamokos planą į savo asmeninį sąrašą?</p>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="modal-btn confirm">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {showEditModal && editedPlan && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content large" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Redaguoti planą</h2>
            </div>
            <div className="modal-body scrollable">
              <div className="edit-group">
                <label>Tema</label>
                <input type="text" value={editedPlan.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} />
              </div>
              <div className="edit-group">
                <label>SMART Tikslas</label>
                <textarea value={editedPlan.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Bendros)</label>
                <textarea value={editedPlan.tasks.general} onChange={e => updateEditedField('tasks.general', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Pagrindinis lygis)</label>
                <textarea value={editedPlan.tasks.mainLevel} onChange={e => updateEditedField('tasks.mainLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>Užduotys (Aukštesnis lygis)</label>
                <textarea value={editedPlan.tasks.highLevel} onChange={e => updateEditedField('tasks.highLevel', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Tema ir darbas</label>
                <textarea value={editedPlan.eDiaryEntry.topicClassworkExpectations} onChange={e => updateEditedField('eDiaryEntry.topicClassworkExpectations', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Pastabos</label>
                <textarea value={editedPlan.eDiaryEntry.notes} onChange={e => updateEditedField('eDiaryEntry.notes', e.target.value)} rows={3} />
              </div>
            </div>
            <div className="modal-actions">
                <button onClick={handleApplyEdit} className="modal-btn confirm">Išsaugoti pakeitimus</button>
                <button onClick={() => setShowEditModal(false)} className="modal-btn cancel">Uždaryti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Pašalinti planą?</h2>
            </div>
            <p className="modal-body-text">Šio veiksmo atšaukti negalėsite. Ar tikrai norite trinti?</p>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); if (activePlanId === deletingPlanId) setLessonPlan(null); }} className="modal-btn delete">Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface EvaluationData {
  methods: string[];
  criteria: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: EvaluationData;
  };
  tasks: {
    general: string;
    highLevel: string;
    mainLevel: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [evaluationCriteria, setEvaluationCriteria] = useState('');
  const [selectedEvaluations, setSelectedEvaluations] = useState<string[]>([]);

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [outsideLocation, setOutsideLocation] = useState('');
  const [outsideGoal, setOutsideGoal] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  // Modal states
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP).
SVARBU: El. dienyno įrašuose (eDiaryEntry) GRIEŽTAI DRAUDŽIAMA naudoti dvitaškius (:) prie pavadinimų. Naudok tik taškus (.).
Pvz. "Tema. Lietuvių kalba ir literatūra", "Klasės darbas. Teksto analizė".

Diferencijavimo skyriuje (differentiation) pateik konkrečias strategijas:
- Gifted (Gabūs): Užduotys reikalaujančios aukštesnių mąstymo gebėjimų, kūrybiškumo, papildomi šaltiniai.
- General (Bendras lygis): Pagrindinės užduotys atitinkančios BP standartą.
- Struggling (Sunkumų turintys): Užduočių skaidymas, vizualinė pagalba, pastoliavimas (scaffolding).

Struktūra:
{
  "generalNotes": "...",
  "lessonType": "...",
  "bpConnections": "...",
  "lessonOverview": { "topic": "...", "goal": "...", "competencies": "...", "evaluation": { "methods": [], "criteria": "..." } },
  "tasks": { "general": "...", "highLevel": "...", "mainLevel": "..." },
  "lessonStages": { "introduction": "...", "theory": "...", "practice": "...", "consolidation": "...", "summary": "..." },
  "differentiation": { "gifted": "...", "general": "...", "struggling": "..." },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": { "topicClassworkExpectations": "...", "homework": "...", "individualHomework": "...", "notes": "...", "isIntegrated": false, "isOutside": false, "eDiaryLessonType": "..." },
  "specialAdvice": "...",
  "consultationAdvice": "...",
  "motivation": "..."
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { return JSON.parse(jsonMatch[0]); } catch (e2) {}
      }
      return null;
    }
  };

  const handleEvaluationToggle = (tag: string) => {
    setSelectedEvaluations(prev => 
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setShowEditModal(false);

    const prompt = `
      Sukurk išsamų pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}, Tema: ${topic}
      - Tipas: ${lessonType}, Tikslas: ${goal}, Veiklos: ${activities}
      - Vertinimo metodai: ${selectedEvaluations.join(', ')}
      - Vertinimo kriterijai: ${evaluationCriteria}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Pamoka už mokyklos ribų: ${isOutsideInput ? `Taip. Vieta: ${outsideLocation}, Tikslas: ${outsideGoal}.` : 'Ne'}

      Ypatingą dėmesį skirk diferencijavimui trims mokinių grupėms.
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan = tryParseJSON(response.text || '');
      if (!parsedPlan) throw new Error("Nepavyko sugeneruoti plano formatu. Bandykite vėl.");

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);

      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
  };

  const handleApplyEdit = () => {
    if (!editedPlan) return;
    setLessonPlan(editedPlan);
    setShowEditModal(false);
    if (activePlanId) {
       executeSavePlan();
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setActivePlanId(p.id);
      setSubject(p.subject || '');
      setGrade(p.grade || '');
      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = JSON.parse(JSON.stringify(editedPlan));
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>
          <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="header-link">
            Griežtai vadovaujantis Lietuvos Bendrosiomis programomis
          </a>
        </p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai</h3>
              <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Pvz. Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžiai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti..." rows={3} />
            </div>
            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., žaidimai..." rows={2} />
            </div>

            <div className="form-group">
              <label>Vertinimo metodai (pasirinkite kelis)</label>
              <div className="evaluation-tags-grid">
                {EVALUATION_TAGS.map(tag => (
                  <label key={tag} className={`tag-checkbox ${selectedEvaluations.includes(tag) ? 'checked' : ''}`}>
                    <input type="checkbox" checked={selectedEvaluations.includes(tag)} onChange={() => handleEvaluationToggle(tag)} />
                    {tag}
                  </label>
                ))}
              </div>
            </div>

            <div className="form-group">
              <label>Vertinimo kriterijai</label>
              <textarea value={evaluationCriteria} onChange={e => setEvaluationCriteria(e.target.value)} placeholder="Aprašykite vertinimo kriterijus..." rows={3} />
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                Integruota pamoka?
              </label>
              {isIntegratedInput && (
                <input 
                  type="text" 
                  value={integrationDetails} 
                  onChange={e => setIntegrationDetails(e.target.value)} 
                  placeholder="Su kuo?" 
                  style={{marginTop: '8px'}}
                />
              )}
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                Už mokyklos ribų?
              </label>
              {isOutsideInput && (
                <div style={{marginTop: '10px', display: 'flex', flexDirection: 'column', gap: '8px'}}>
                  <input 
                    type="text" 
                    value={outsideLocation} 
                    onChange={e => setOutsideLocation(e.target.value)} 
                    placeholder="Kur? (pvz., Muziejus, parkas)" 
                  />
                  <input 
                    type="text" 
                    value={outsideGoal} 
                    onChange={e => setOutsideGoal(e.target.value)} 
                    placeholder="Kokiu ugdymo tikslu?" 
                  />
                  <p className="helper-text">Rekomenduojami tikslai: tyrinėjimas, stebėjimas, patirtinis mokymasis.</p>
                </div>
              )}
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? "Generuojama..." : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti planuose..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="mini-delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>DI kuria jūsų pamokos planą...</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite duomenis kairėje ir spauskite „Generuoti planą“.</p>
              <p style={{marginTop: '15px', opacity: 0.8}}>DI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                <button onClick={() => { setEditedPlan(lessonPlan); setShowEditModal(true); }} className="edit-modal-btn">Redaguoti ✏️</button>
              </div>

              <div className="card">
                <h3>📚 Sąsajos su BP</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
              </div>

              <div className="card">
                <h3>📖 Apžvalga</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation.methods.join(', ')}</p>
              </div>

              <div className="card">
                <h3>📝 Diferencijavimas ir individualizavimas</h3>
                <div style={{display: 'flex', flexDirection: 'column', gap: '10px'}}>
                  <div>
                    <span className="diary-label" style={{color: 'var(--success-color)'}}>Gabūs mokiniai</span>
                    <p className="diary-text">{lessonPlan.differentiation.gifted}</p>
                  </div>
                  <div>
                    <span className="diary-label" style={{color: 'var(--primary-color)'}}>Pagrindinis lygis</span>
                    <p className="diary-text">{lessonPlan.differentiation.general}</p>
                  </div>
                  <div>
                    <span className="diary-label" style={{color: 'var(--error-color)'}}>Mokiniai, turintys sunkumų</span>
                    <p className="diary-text">{lessonPlan.differentiation.struggling}</p>
                  </div>
                </div>
              </div>

              <div className="card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'notes'].map(key => (
                  <div key={key} className="diary-field-wrapper">
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'Namų darbai' : 'Pastabos'}</label>
                    <div className="diary-field">
                      <span className="diary-text">{(lessonPlan.eDiaryEntry as any)[key]}</span>
                      <button onClick={() => handleCopy((lessonPlan.eDiaryEntry as any)[key], key)} className="copy-button">Kopijuoti</button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card" style={{borderLeftColor: 'var(--secondary-color)'}}>
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p style={{fontStyle: 'italic'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* MODALAI */}
      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Patvirtinkite išsaugojimą</h2>
            </div>
            <p className="modal-body-text">Ar norite išsaugoti šį pamokos planą į savo asmeninį sąrašą?</p>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="modal-btn confirm">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {showEditModal && editedPlan && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content large" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Redaguoti planą</h2>
            </div>
            <div className="modal-body scrollable">
              <div className="edit-group">
                <label>Tema</label>
                <input type="text" value={editedPlan.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} />
              </div>
              <div className="edit-group">
                <label>SMART Tikslas</label>
                <textarea value={editedPlan.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} rows={3} />
              </div>

              <div className="edit-divider">Diferencijavimas</div>
              <div className="edit-group">
                <label>Gabūs mokiniai</label>
                <textarea value={editedPlan.differentiation.gifted} onChange={e => updateEditedField('differentiation.gifted', e.target.value)} rows={2} />
              </div>
              <div className="edit-group">
                <label>Bendras lygis</label>
                <textarea value={editedPlan.differentiation.general} onChange={e => updateEditedField('differentiation.general', e.target.value)} rows={2} />
              </div>
              <div className="edit-group">
                <label>Sunkumų turintys mokiniai</label>
                <textarea value={editedPlan.differentiation.struggling} onChange={e => updateEditedField('differentiation.struggling', e.target.value)} rows={2} />
              </div>

              <div className="edit-divider">El. dienynas</div>
              <div className="edit-group">
                <label>El. dienynas: Tema ir darbas</label>
                <textarea value={editedPlan.eDiaryEntry.topicClassworkExpectations} onChange={e => updateEditedField('eDiaryEntry.topicClassworkExpectations', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Pastabos</label>
                <textarea value={editedPlan.eDiaryEntry.notes} onChange={e => updateEditedField('eDiaryEntry.notes', e.target.value)} rows={3} />
              </div>
            </div>
            <div className="modal-actions">
                <button onClick={handleApplyEdit} className="modal-btn confirm">Išsaugoti pakeitimus</button>
                <button onClick={() => setShowEditModal(false)} className="modal-btn cancel">Uždaryti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Pašalinti planą?</h2>
            </div>
            <p className="modal-body-text">Šio veiksmo atšaukti negalėsite. Ar tikrai norite trinti?</p>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); if (activePlanId === deletingPlanId) setLessonPlan(null); }} className="modal-btn delete">Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  --primary-color: #3b82f6;
  --secondary-color: #10b981;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --error-color: #ef4444;
  --success-color: #10b981;
  --info-color: #8b5cf6;

  --spacing-md: 1rem;
  --border-radius-lg: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container { max-width: 1400px; margin: 0 auto; padding: var(--spacing-md); }

.header {
  text-align: center;
  margin-bottom: 2rem;
  padding: 1.5rem;
  background-color: var(--surface-color);
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.header h1 { color: var(--heading-color); margin-bottom: 0.25rem; }
.header-link { color: var(--primary-color); text-decoration: none; font-size: 0.9rem; font-weight: 600; }

.header-sections {
  display: flex;
  justify-content: center;
  margin-top: 1rem;
  flex-wrap: wrap;
  gap: 1.5rem;
  border-top: 1px solid var(--border-color);
  padding-top: 1.2rem;
}

.resource-links, .tool-links {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.resource-links h3, .tool-links h3 {
  font-size: 0.85rem;
  color: var(--text-color-light);
  margin-right: 4px;
}

.mini-link {
  color: var(--primary-color);
  text-decoration: none;
  font-size: 0.8rem;
  padding: 4px 10px;
  background: rgba(59, 130, 246, 0.1);
  border-radius: 6px;
  border: 1px solid rgba(59, 130, 246, 0.2);
}

.tool-button {
  padding: 6px 14px;
  border-radius: 8px;
  color: white;
  text-decoration: none;
  font-size: 0.8rem;
  font-weight: bold;
}
.tool-button.classroom { background: #1e8e3e; }
.tool-button.miro { background: #ffcc00; color: black; }
.tool-button.canva { background: #00c4cc; }

/* Main Grid */
.main-content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 1024px) {
  .main-content { grid-template-columns: 380px 1fr; }
}

.form-container, .results-container {
  background-color: var(--surface-color);
  padding: 1.5rem;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border-color);
}

.form-container h2 { color: var(--heading-color); margin-bottom: 1.5rem; font-size: 1.25rem; }

/* Forms */
.form-group { margin-bottom: 1.2rem; }
.form-group label { display: block; color: var(--heading-color); margin-bottom: 8px; font-weight: 500; font-size: 0.9rem; }
.form-group input, .form-group textarea, .form-group select {
  width: 100%;
  padding: 12px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: #0f172a;
  color: white;
  font-size: 0.95rem;
  font-family: inherit;
}

.evaluation-tags-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tag-checkbox {
  padding: 10px;
  background: #0f172a;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 0.75rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s;
}

.tag-checkbox.checked { border-color: var(--primary-color); background: rgba(59, 130, 246, 0.1); color: white; }

.checkbox-label {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  color: var(--heading-color);
  font-size: 0.9rem;
  font-weight: 500;
  margin-top: 10px;
}

.checkbox-label input[type="checkbox"] {
  width: 18px;
  height: 18px;
  cursor: pointer;
}

.helper-text {
  font-size: 0.75rem;
  color: var(--text-color);
  margin-top: 4px;
  font-style: italic;
  padding-left: 28px;
}

.generate-button {
  width: 100%;
  padding: 14px;
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  color: white;
  border: none;
  border-radius: 10px;
  font-weight: bold;
  font-size: 1rem;
  cursor: pointer;
  box-shadow: 0 4px 15px rgba(0,0,0,0.2);
  margin-top: 1rem;
}

/* Modals */
.modal-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
  padding: 20px;
}

.modal-content {
  background: var(--surface-color);
  border: 2px solid var(--primary-color);
  border-radius: 16px;
  width: 100%;
  max-width: 500px;
  padding: 2rem;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
}

.modal-content.large { max-width: 850px; max-height: 90vh; display: flex; flex-direction: column; }
.modal-body.scrollable { overflow-y: auto; flex: 1; margin: 1rem 0; padding-right: 1rem; }

.modal-header h2 { color: var(--heading-color); margin-bottom: 1rem; border-bottom: 1px solid var(--border-color); padding-bottom: 0.5rem; }
.modal-body-text { color: var(--text-color-light); margin-bottom: 2rem; text-align: center; }
.modal-actions { display: flex; gap: 1rem; }

.modal-btn {
  flex: 1;
  padding: 12px;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
  border: none;
  font-family: inherit;
}

.modal-btn.confirm { background: var(--success-color); color: white; }
.modal-btn.cancel { background: #334155; color: white; }
.modal-btn.delete { background: var(--error-color); color: white; }

.edit-divider {
  padding: 10px 0;
  margin: 15px 0 10px;
  color: var(--primary-color);
  font-weight: bold;
  border-bottom: 2px solid var(--border-color);
  font-size: 0.9rem;
}

/* Plan Result Card */
.lesson-plan-result {
  animation: fadeIn 0.4s ease-out;
}

.card {
  background: #1e293b;
  border-left: 4px solid var(--primary-color);
  padding: 1.2rem;
  margin-bottom: 1.5rem;
  border-radius: 4px 12px 12px 4px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.15);
}

.card h3 { color: var(--heading-color); margin-bottom: 0.8rem; font-size: 1.1rem; }

.diary-field-wrapper { margin-bottom: 1.2rem; }
.diary-label { font-size: 0.8rem; color: var(--primary-color); display: block; margin-bottom: 6px; font-weight: 600; }
.diary-field {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background: #0f172a;
  padding: 12px;
  border-radius: 10px;
  gap: 1rem;
}
.diary-text { font-size: 0.95rem; flex: 1; white-space: pre-wrap; color: var(--text-color-light); }
.copy-button { background: var(--primary-color); color: white; border: none; padding: 6px 12px; border-radius: 6px; font-size: 0.75rem; cursor: pointer; font-weight: bold; }

.export-container { display: flex; gap: 12px; margin-bottom: 1.5rem; }
.save-button { background: var(--success-color); color: white; padding: 12px; border-radius: 10px; flex: 1; border: none; cursor: pointer; font-weight: bold; font-size: 0.95rem; }
.edit-modal-btn { background: var(--info-color); color: white; padding: 12px; border-radius: 10px; flex: 1; border: none; cursor: pointer; font-weight: bold; font-size: 0.95rem; }

/* Saved Plans Sidebar */
.saved-plans-container { margin-top: 2rem; border-top: 1px solid var(--border-color); padding-top: 1.5rem; }
.search-input { width: 100%; padding: 10px; background: #0f172a; border: 1px solid var(--border-color); border-radius: 8px; color: white; margin-bottom: 1rem; font-family: inherit; }
.saved-plans-list { list-style: none; max-height: 350px; overflow-y: auto; }
.saved-plans-list li {
  padding: 12px; background: rgba(15, 23, 42, 0.5); border-radius: 8px; margin-bottom: 8px; cursor: pointer;
  display: flex; justify-content: space-between; align-items: center; border: 1px solid transparent;
}
.saved-plans-list li.active { border-color: var(--primary-color); background: rgba(59, 130, 246, 0.1); }
.plan-title { font-size: 0.85rem; color: var(--text-color-light); font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 180px; }
.mini-delete-button { color: var(--error-color); background: none; border: none; cursor: pointer; font-size: 1rem; padding: 4px; }

/* States */
.loading-overlay { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 350px; }
.spinner-large { width: 45px; height: 45px; border: 4px solid rgba(59, 130, 246, 0.2); border-top-color: var(--primary-color); border-radius: 50%; animation: spin 1s linear infinite; margin-bottom: 1.2rem; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.welcome-message { text-align: center; padding: 4rem 1rem; }
.welcome-message h2 { color: var(--heading-color); margin-bottom: 0.8rem; }

/* Edit Inputs */
.edit-group { margin-bottom: 1.2rem; }
.edit-group label { display: block; color: var(--text-color-light); margin-bottom: 6px; font-size: 0.85rem; font-weight: 600; }
.edit-group input, .edit-group textarea {
  width: 100%; padding: 12px; background: #0f172a; border: 1px solid var(--border-color); color: white; border-radius: 8px; font-family: inherit; font-size: 0.95rem;
}

import React, { useState, useRef, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { GoogleGenAI, Chat, Type } from '@google/genai';

type LessonCategory = 'Įvadinė' | 'Įtvirtinimo' | 'Apibendrinamoji' | 'Vertinamoji' | '';

interface EDiaryEntry {
  topicClassworkExpectations: string;
  homework: string;
  individualHomework: string;
  notes: string;
  isIntegrated: boolean;
  isOutside: boolean;
  eDiaryLessonType: string;
}

interface EvaluationData {
  methods: string[];
  criteria: string;
}

interface LessonPlan {
  generalNotes: string;
  lessonType?: LessonCategory;
  bpConnections: string;
  lessonOverview: {
    topic: string;
    goal: string;
    competencies: string;
    evaluation: EvaluationData;
  };
  tasks: {
    general: string;
    highLevel: string;
    mainLevel: string;
  };
  lessonStages: {
    introduction: string;
    theory: string;
    practice: string;
    consolidation: string;
    summary: string;
  };
  differentiation: {
    gifted: string;
    general: string;
    struggling: string;
  };
  homework: {
    purpose: string;
    gifted: string;
    general: string;
    struggling: string;
  };
  eDiaryEntry: EDiaryEntry;
  consultationAdvice?: string;
  specialAdvice?: string; 
  motivation: string;
}

interface SavedPlan {
  id: string;
  title: string;
  plan: LessonPlan;
  createdAt: string;
  comments?: string;
  subject?: string;
  grade?: string;
  lessonType?: LessonCategory;
}

const EVALUATION_TAGS = [
  'Paprastas pažymys', 'Kontrolinis darbas', 'Savarankiškas darbas', 'Projektinis darbas',
  'Integruotas tarpdalykinis įvertinimas', 'Tarpinis atsiskaitymas', 'Galutinis atsiskaitymas',
  'Atsiskaitomasis darbas', 'Formuojamojo vertinimo darbas', 'Probleminio tipo užduotis'
];

const App = () => {
  const [grade, setGrade] = useState('');
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState('');
  const [lessonType, setLessonType] = useState<LessonCategory>('');
  const [goal, setGoal] = useState('');
  const [activities, setActivities] = useState('');
  const [evaluationCriteria, setEvaluationCriteria] = useState('');
  const [selectedEvaluations, setSelectedEvaluations] = useState<string[]>([]);

  const [isIntegratedInput, setIsIntegratedInput] = useState(false);
  const [integrationDetails, setIntegrationDetails] = useState('');
  const [isOutsideInput, setIsOutsideInput] = useState(false);
  const [outsideLocation, setOutsideLocation] = useState('');
  const [outsideGoal, setOutsideGoal] = useState('');

  const [lessonPlan, setLessonPlan] = useState<LessonPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  // Modal states
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editedPlan, setEditedPlan] = useState<LessonPlan | null>(null);

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [deletingPlanId, setDeletingPlanId] = useState<string | null>(null);

  useEffect(() => {
    try {
      const storedPlans = localStorage.getItem('savedLessonPlans');
      if (storedPlans) setSavedPlans(JSON.parse(storedPlans));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('savedLessonPlans', JSON.stringify(savedPlans));
    } catch (e) { console.error(e); }
  }, [savedPlans]);

  const systemInstruction = `Tu esi ekspertas pedagogas, puikiai išmanantis Lietuvos Bendrąsias ugdymo programas (BP).
SVARBU: El. dienyno įrašuose (eDiaryEntry) GRIEŽTAI DRAUDŽIAMA naudoti dvitaškius (:) prie pavadinimų. Naudok tik taškus (.).
Pvz. "Tema. Lietuvių kalba ir literatūra", "Klasės darbas. Teksto analizė".

Struktūrizuotas diferencijavimas (differentiation) turi apimti:
- Gifted (Gabūs): Užduotys, kurios skatina analitinį, kritinį ir kūrybinį mąstymą (BLOOM taksonomijos viršūnė). Pateik sudėtingesnius tekstus, atvirus klausimus, projektinę veiklą.
- General (Vidutiniai): Užduotys, užtikrinančios BP reikalavimų pasiekimą (supratimas, taikymas).
- Struggling (Sunkumų turintys): Strategijos: vizualizacija, pagalbiniai klausimai, užduočių skaidymas į mažesnius etapus, sąvokų žodynėliai.

Struktūra:
{
  "generalNotes": "...",
  "lessonType": "...",
  "bpConnections": "...",
  "lessonOverview": { "topic": "...", "goal": "...", "competencies": "...", "evaluation": { "methods": [], "criteria": "..." } },
  "tasks": { "general": "...", "highLevel": "...", "mainLevel": "..." },
  "lessonStages": { "introduction": "...", "theory": "...", "practice": "...", "consolidation": "...", "summary": "..." },
  "differentiation": { "gifted": "...", "general": "...", "struggling": "..." },
  "homework": { "purpose": "...", "gifted": "...", "general": "...", "struggling": "..." },
  "eDiaryEntry": { "topicClassworkExpectations": "...", "homework": "...", "individualHomework": "...", "notes": "...", "isIntegrated": false, "isOutside": false, "eDiaryLessonType": "..." },
  "specialAdvice": "...",
  "consultationAdvice": "...",
  "motivation": "..."
}`;

  const tryParseJSON = (text: string): LessonPlan | null => {
    try {
      return JSON.parse(text);
    } catch (e) {
      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { return JSON.parse(jsonMatch[0]); } catch (e2) {}
      }
      return null;
    }
  };

  const handleEvaluationToggle = (tag: string) => {
    setSelectedEvaluations(prev => 
      prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
    );
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!grade || !subject || !topic) {
      setError('Užpildykite privalomus laukus (*).');
      return;
    }

    setIsLoading(true);
    setError(null);
    setShowEditModal(false);

    const prompt = `
      Sukurk išsamų ir struktūrizuotą pamokos planą:
      - Dalykas: ${subject}, Klasė: ${grade}, Tema: ${topic}
      - Tipas: ${lessonType}, Tikslas: ${goal}, Veiklos: ${activities}
      - Vertinimo metodai: ${selectedEvaluations.join(', ')}
      - Vertinimo kriterijai: ${evaluationCriteria}
      - Integracija: ${isIntegratedInput ? integrationDetails : 'Ne'}
      - Pamoka už mokyklos ribų: ${isOutsideInput ? `Taip. Vieta: ${outsideLocation}, Tikslas: ${outsideGoal}.` : 'Ne'}

      GRIEŽTAI: Pateik labai konkrečias diferencijavimo strategijas trims mokinių grupėms (Gabūs, Vidutiniai, Sunkumų turintys).
    `;

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" },
      });

      const parsedPlan = tryParseJSON(response.text || '');
      if (!parsedPlan) throw new Error("Nepavyko sugeneruoti plano formatu. Bandykite vėl.");

      const sanitizedPlan: LessonPlan = {
        ...parsedPlan,
        eDiaryEntry: {
          ...parsedPlan.eDiaryEntry,
          isIntegrated: isIntegratedInput,
          isOutside: isOutsideInput,
          eDiaryLessonType: parsedPlan.eDiaryEntry?.eDiaryLessonType || parsedPlan.lessonType || lessonType || ''
        }
      };

      setLessonPlan(sanitizedPlan);
      setEditedPlan(sanitizedPlan);
      setActivePlanId(null);

      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    } catch (e: any) {
      setError(`Klaida: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopy = (text: string, field: string) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
    });
  };

  const executeSavePlan = () => {
    const planToSave = editedPlan || lessonPlan;
    if (!planToSave) return;

    const newPlan: SavedPlan = {
      id: activePlanId || `plan-${Date.now()}`,
      title: `${subject} ${grade}: ${planToSave.lessonOverview.topic}`,
      plan: planToSave,
      createdAt: new Date().toISOString(),
      grade, subject, lessonType: planToSave.lessonType || lessonType
    };

    if (activePlanId) {
      setSavedPlans(prev => prev.map(p => p.id === activePlanId ? newPlan : p));
    } else {
      setSavedPlans([newPlan, ...savedPlans]);
      setActivePlanId(newPlan.id);
    }

    setShowSaveConfirm(false);
    setLessonPlan(planToSave);
  };

  const handleApplyEdit = () => {
    if (!editedPlan) return;
    setLessonPlan(editedPlan);
    setShowEditModal(false);
    if (activePlanId) {
       executeSavePlan();
    }
  };

  const handleLoadPlan = (id: string) => {
    const p = savedPlans.find(x => x.id === id);
    if (p) {
      setLessonPlan(p.plan);
      setEditedPlan(p.plan);
      setActivePlanId(p.id);
      setSubject(p.subject || '');
      setGrade(p.grade || '');
      if (window.innerWidth < 1024) {
        document.querySelector('.results-container')?.scrollIntoView({ behavior: 'smooth' });
      }
    }
  };

  const updateEditedField = (path: string, value: any) => {
    if (!editedPlan) return;
    const newPlan = JSON.parse(JSON.stringify(editedPlan));
    const parts = path.split('.');
    let current: any = newPlan;
    for (let i = 0; i < parts.length - 1; i++) {
      current = current[parts[i]];
    }
    current[parts[parts.length - 1]] = value;
    setEditedPlan(newPlan);
  };

  const processedPlans = [...savedPlans]
    .filter(p => p.title.toLowerCase().includes(searchQuery.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="container">
      <header className="header">
        <h1>Pamokos plano rengimas ✏️</h1>
        <p>
          <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="header-link">
            Griežtai vadovaujantis Lietuvos Bendrosiomis programomis
          </a>
        </p>

        <div className="header-sections">
            <div className="resource-links">
              <h3>📚 Šaltiniai</h3>
              <a href="https://emokykla.lt/bendrosios-programos" target="_blank" rel="noopener noreferrer" className="mini-link">Programos (BP)</a>
              <a href="https://emokykla.lt/skaitmenines-mokymo-priemones" target="_blank" rel="noopener noreferrer" className="mini-link">Priemonės</a>
              <a href="https://emokykla.lt/bendrosios-programos/kompetencijos" target="_blank" rel="noopener noreferrer" className="mini-link">Kompetencijos</a>
            </div>

            <div className="tool-links">
              <h3>🛠️ Įrankiai</h3>
              <a href="https://classroom.google.com" target="_blank" rel="noopener noreferrer" className="tool-button classroom">Classroom</a>
              <a href="https://miro.com" target="_blank" rel="noopener noreferrer" className="tool-button miro">Miro</a>
              <a href="https://canva.com" target="_blank" rel="noopener noreferrer" className="tool-button canva">Canva</a>
            </div>
        </div>
      </header>

      <main className="main-content">
        <div className="form-container">
          <h2>Pamokos informacija</h2>
          <form onSubmit={handleGenerate}>
            <div className="form-group">
              <label>Dalykas *</label>
              <input type="text" value={subject} onChange={e => setSubject(e.target.value)} placeholder="Pvz. Lietuvių kalba ir literatūra" required />
            </div>
            <div className="form-group">
              <label>Klasė / Grupė *</label>
              <input type="text" value={grade} onChange={e => setGrade(e.target.value)} placeholder="pvz., 7a" required />
            </div>
            <div className="form-group">
              <label>Tema *</label>
              <input type="text" value={topic} onChange={e => setTopic(e.target.value)} placeholder="pvz., Veiksmažodžiai" required />
            </div>
            <div className="form-group">
              <label>Pamokos tipas</label>
              <select value={lessonType} onChange={e => setLessonType(e.target.value as LessonCategory)}>
                <option value="">-- Pasirinkite --</option>
                <option value="Įvadinė">Įvadinė</option>
                <option value="Įtvirtinimo">Įtvirtinimo</option>
                <option value="Apibendrinamoji">Apibendrinamoji</option>
                <option value="Vertinamoji">Vertinamoji</option>
              </select>
            </div>
            <div className="form-group">
              <label>Tikslas (Mokiniai gebės...)</label>
              <textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="pvz., atpažinti..." rows={3} />
            </div>

            <div className="differentiation-guide">
              <h4>💡 Diferencijavimo gidas</h4>
              <ul>
                <li><strong>Gabūs:</strong> Analizė, kūryba, sintezė.</li>
                <li><strong>Vidutiniai:</strong> Suvokimas, taikymas pagal pavyzdį.</li>
                <li><strong>Sunkumų turintys:</strong> Vizualizacija, skaidymas, parama.</li>
              </ul>
            </div>

            <div className="form-group">
              <label>Papildomos idėjos</label>
              <textarea value={activities} onChange={e => setActivities(e.target.value)} placeholder="pvz., žaidimai..." rows={2} />
            </div>

            <div className="form-group">
              <label>Vertinimo metodai (pasirinkite kelis)</label>
              <div className="evaluation-tags-grid">
                {EVALUATION_TAGS.map(tag => (
                  <label key={tag} className={`tag-checkbox ${selectedEvaluations.includes(tag) ? 'checked' : ''}`}>
                    <input type="checkbox" checked={selectedEvaluations.includes(tag)} onChange={() => handleEvaluationToggle(tag)} />
                    {tag}
                  </label>
                ))}
              </div>
            </div>

            <div className="form-group">
              <label>Vertinimo kriterijai</label>
              <textarea value={evaluationCriteria} onChange={e => setEvaluationCriteria(e.target.value)} placeholder="Aprašykite vertinimo kriterijus..." rows={3} />
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isIntegratedInput} onChange={e => setIsIntegratedInput(e.target.checked)} />
                Integruota pamoka?
              </label>
              {isIntegratedInput && (
                <input 
                  type="text" 
                  value={integrationDetails} 
                  onChange={e => setIntegrationDetails(e.target.value)} 
                  placeholder="Su kuo?" 
                  style={{marginTop: '8px'}}
                />
              )}
            </div>

            <div className="form-group">
              <label className="checkbox-label">
                <input type="checkbox" checked={isOutsideInput} onChange={e => setIsOutsideInput(e.target.checked)} />
                Už mokyklos ribų?
              </label>
              {isOutsideInput && (
                <div style={{marginTop: '10px', display: 'flex', flexDirection: 'column', gap: '8px'}}>
                  <input 
                    type="text" 
                    value={outsideLocation} 
                    onChange={e => setOutsideLocation(e.target.value)} 
                    placeholder="Kur? (pvz., Muziejus, parkas)" 
                  />
                  <input 
                    type="text" 
                    value={outsideGoal} 
                    onChange={e => setOutsideGoal(e.target.value)} 
                    placeholder="Kokiu ugdymo tikslu?" 
                  />
                  <p className="helper-text">Rekomenduojami tikslai: tyrinėjimas, stebėjimas, patirtinis mokymasis.</p>
                </div>
              )}
            </div>

            <button type="submit" disabled={isLoading} className="generate-button">
              {isLoading ? "Generuojama..." : "Generuoti planą 🚀"}
            </button>
          </form>

          <div className="saved-plans-container">
            <h3>Išsaugoti planai</h3>
            <input type="text" placeholder="Ieškoti planuose..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="search-input" />
            <ul className="saved-plans-list">
              {processedPlans.map(p => (
                <li key={p.id} onClick={() => handleLoadPlan(p.id)} className={activePlanId === p.id ? 'active' : ''}>
                  <div className="plan-info">
                    <span className="plan-title">{p.title}</span>
                    <span className="meta-tag">{p.createdAt.split('T')[0]}</span>
                  </div>
                  <button onClick={e => { e.stopPropagation(); setDeletingPlanId(p.id); }} className="mini-delete-button">✖</button>
                </li>
              ))}
            </ul>
          </div>
        </div>

        <div className="results-container">
          {isLoading && (
            <div className="loading-overlay">
              <div className="spinner-large"></div>
              <p>DI kuria jūsų pamokos planą...</p>
            </div>
          )}
          {error && <div className="error-message">{error}</div>}

          {!isLoading && !lessonPlan && (
            <div className="welcome-message">
              <h2>Sveiki! 👋</h2>
              <p>Užpildykite duomenis kairėje ir spauskite „Generuoti planą“.</p>
              <p style={{marginTop: '15px', opacity: 0.8}}>DI paruoš išsamų planą vadovaujantis Lietuvos švietimo standartais.</p>
            </div>
          )}

          {lessonPlan && (
            <div className="lesson-plan-result">
              <div className="export-container">
                <button onClick={() => setShowSaveConfirm(true)} className="save-button">Išsaugoti 💾</button>
                <button onClick={() => { setEditedPlan(lessonPlan); setShowEditModal(true); }} className="edit-modal-btn">Redaguoti ✏️</button>
              </div>

              <div className="card">
                <h3>📚 Sąsajos su BP</h3>
                <p style={{whiteSpace: 'pre-wrap'}}>{lessonPlan.bpConnections}</p>
              </div>

              <div className="card">
                <h3>📖 Apžvalga</h3>
                <p><strong>Tema:</strong> {lessonPlan.lessonOverview.topic}</p>
                <p><strong>Tikslas:</strong> {lessonPlan.lessonOverview.goal}</p>
                <p><strong>Vertinimas:</strong> {lessonPlan.lessonOverview.evaluation.methods.join(', ')}</p>
              </div>

              <div className="card results-diff-section">
                <h3>📝 Diferencijavimas ir individualizavimas</h3>
                <div className="diff-grid">
                  <div className="diff-item gifted">
                    <span className="diff-header">Gabūs mokiniai 🌟</span>
                    <p className="diff-text">{lessonPlan.differentiation.gifted}</p>
                  </div>
                  <div className="diff-item average">
                    <span className="diff-header">Vidutiniai mokiniai ✅</span>
                    <p className="diff-text">{lessonPlan.differentiation.general}</p>
                  </div>
                  <div className="diff-item struggling">
                    <span className="diff-header">Mokiniai su sunkumais 🛡️</span>
                    <p className="diff-text">{lessonPlan.differentiation.struggling}</p>
                  </div>
                </div>
              </div>

              <div className="card">
                <h3>✍️ El. dienyno įrašai</h3>
                {['topicClassworkExpectations', 'homework', 'notes'].map(key => (
                  <div key={key} className="diary-field-wrapper">
                    <label className="diary-label">{key === 'topicClassworkExpectations' ? 'Tema ir darbas' : key === 'homework' ? 'Namų darbai' : 'Pastabos'}</label>
                    <div className="diary-field">
                      <span className="diary-text">{(lessonPlan.eDiaryEntry as any)[key]}</span>
                      <button onClick={() => handleCopy((lessonPlan.eDiaryEntry as any)[key], key)} className="copy-button">Kopijuoti</button>
                    </div>
                  </div>
                ))}
              </div>

              <div className="card" style={{borderLeftColor: 'var(--secondary-color)'}}>
                 <h3>💖 Motyvacinė žinutė</h3>
                 <p style={{fontStyle: 'italic'}}>{lessonPlan.motivation}</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* MODALAI */}
      {showSaveConfirm && (
        <div className="modal-overlay" onClick={() => setShowSaveConfirm(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Patvirtinkite išsaugojimą</h2>
            </div>
            <p className="modal-body-text">Ar norite išsaugoti šį pamokos planą į savo asmeninį sąrašą?</p>
            <div className="modal-actions">
                <button onClick={executeSavePlan} className="modal-btn confirm">Taip, išsaugoti</button>
                <button onClick={() => setShowSaveConfirm(false)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {showEditModal && editedPlan && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content large" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Redaguoti planą</h2>
            </div>
            <div className="modal-body scrollable">
              <div className="edit-group">
                <label>Tema</label>
                <input type="text" value={editedPlan.lessonOverview.topic} onChange={e => updateEditedField('lessonOverview.topic', e.target.value)} />
              </div>
              <div className="edit-group">
                <label>SMART Tikslas</label>
                <textarea value={editedPlan.lessonOverview.goal} onChange={e => updateEditedField('lessonOverview.goal', e.target.value)} rows={3} />
              </div>

              <div className="edit-divider">Diferencijavimas</div>
              <div className="edit-group">
                <label>Gabūs mokiniai</label>
                <textarea value={editedPlan.differentiation.gifted} onChange={e => updateEditedField('differentiation.gifted', e.target.value)} rows={2} />
              </div>
              <div className="edit-group">
                <label>Bendras lygis</label>
                <textarea value={editedPlan.differentiation.general} onChange={e => updateEditedField('differentiation.general', e.target.value)} rows={2} />
              </div>
              <div className="edit-group">
                <label>Sunkumų turintys mokiniai</label>
                <textarea value={editedPlan.differentiation.struggling} onChange={e => updateEditedField('differentiation.struggling', e.target.value)} rows={2} />
              </div>

              <div className="edit-divider">El. dienynas</div>
              <div className="edit-group">
                <label>El. dienynas: Tema ir darbas</label>
                <textarea value={editedPlan.eDiaryEntry.topicClassworkExpectations} onChange={e => updateEditedField('eDiaryEntry.topicClassworkExpectations', e.target.value)} rows={3} />
              </div>
              <div className="edit-group">
                <label>El. dienynas: Pastabos</label>
                <textarea value={editedPlan.eDiaryEntry.notes} onChange={e => updateEditedField('eDiaryEntry.notes', e.target.value)} rows={3} />
              </div>
            </div>
            <div className="modal-actions">
                <button onClick={handleApplyEdit} className="modal-btn confirm">Išsaugoti pakeitimus</button>
                <button onClick={() => setShowEditModal(false)} className="modal-btn cancel">Uždaryti</button>
            </div>
          </div>
        </div>
      )}

      {deletingPlanId && (
        <div className="modal-overlay" onClick={() => setDeletingPlanId(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Pašalinti planą?</h2>
            </div>
            <p className="modal-body-text">Šio veiksmo atšaukti negalėsite. Ar tikrai norite trinti?</p>
            <div className="modal-actions">
                <button onClick={() => { setSavedPlans(savedPlans.filter(p => p.id !== deletingPlanId)); setDeletingPlanId(null); if (activePlanId === deletingPlanId) setLessonPlan(null); }} className="modal-btn delete">Trinti</button>
                <button onClick={() => setDeletingPlanId(null)} className="modal-btn cancel">Atšaukti</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

:root {
  --primary-color: #3b82f6;
  --secondary-color: #10b981;
  --background-color: #0f172a;
  --surface-color: #1e293b;
  --text-color: #94a3b8;
  --text-color-light: #cbd5e1;
  --heading-color: #f8fafc;
  --border-color: #334155;
  --error-color: #ef4444;
  --success-color: #10b981;
  --info-color: #8b5cf6;

  --spacing-md: 1rem;
  --border-radius-lg: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--background-color);
  color: var(--text-color);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container { max-width: 1400px; margin: 0 auto; padding: var(--spacing-md); }

.header {
  text-align: center;
  margin-bottom: 2rem;
  padding: 1.5rem;
